        qty = int.parse(c);
        int prev = stock[wh] ?? 0;
        int next = op == '+' ? prev + qty : prev - qty;
        stock[wh] = next;
        if (next < 0) alerts.add(wh);
        state = 0;
      }
    }
    i++;
  }
  return alerts;
}

