import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<int> requests, int currentFloor, int maxStops) {
  Map<int, int> counts = {};

  for (int floor in requests) {
    if (floor == currentFloor) {
      continue;
    }
    counts[floor] = (counts[floor] ?? 0) + 1;
  }

  List<int> above = [];
  List<int> below = [];

  for (int floor in counts.keys) {
    if (floor > currentFloor) {
      above.add(floor);
    } else {
      below.add(floor);
    }
  }

  above.sort();
  below.sort((a, b) => b.compareTo(a));

  Set<int> result = {};
  bool goUp = above.length >= below.length;
  int upIndex = 0;
  int downIndex = 0;

  while (result.length < maxStops &&
      (upIndex < above.length || downIndex < below.length)) {
    if (goUp) {
      if (upIndex < above.length) {
        int floor = above[upIndex];
        if (upIndex == 0 || counts[floor]! >= 2) {
          result.add(floor);
        }
        upIndex++;
      }
    } else {
      if (downIndex < below.length) {
        int floor = below[downIndex];
        if (downIndex == 0 || counts[floor]! >= 2) {
          result.add(floor);
        }
        downIndex++;
      }
    }

    goUp = !goUp;
  }

  return result;
}

