Set<int> fn0(List<int> transactions, int initialBalance) {
  Set<int> peaks = {};
  Set<String> visited = {};

  void explore(int i, int balance, int maxSoFar) {
    if (i == transactions.length) {
      peaks.add(maxSoFar);
      return;
    }
    String state = '$i,$balance,$maxSoFar';
    if (visited.contains(state)) return;
    visited.add(state);

    explore(i + 1, balance, maxSoFar);

    int newBalance = balance + transactions[i];
    if (newBalance >= 0) {
      explore(i + 1, newBalance, maxSoFar > newBalance ? maxSoFar : newBalance);
    }
  }

  explore(0, initialBalance, initialBalance);
  return peaks;
}

