List<String> fn0(List<List<int>> dailyRequests, int maxPerDay, int maintenanceEvery) {
  List<String> result = [];
  Set<int> deferred = {};
  int day = 0;
  bool noMaintenance = maintenanceEvery <= 1;

  for (int i = 0; i < dailyRequests.length; i++) {
    day = i;
    deferred.addAll(dailyRequests[i]);
    if (!noMaintenance && day % maintenanceEvery == 0) {
      result.add('Day $day: MAINTENANCE');
    } else {
      if (deferred.isEmpty) {
        result.add('Day $day: IDLE');
      } else {
        List<int> sorted = deferred.toList()..sort();
        List<int> served = sorted.take(maxPerDay).toList();
        deferred = sorted.skip(maxPerDay).toSet();
        result.add('Day $day: served $served');
      }
    }
  }

  while (deferred.isNotEmpty) {
    day++;
    if (!noMaintenance && day % maintenanceEvery == 0) {
      result.add('Day $day: MAINTENANCE');
    } else {
      List<int> sorted = deferred.toList()..sort();
      List<int> served = sorted.take(maxPerDay).toList();
      deferred = sorted.skip(maxPerDay).toSet();
      result.add('Day $day: served $served');
    }
  }

  return result;
}

