    final qR = (p[0] ~/ 32) * 32;
    final qG = (p[1] ~/ 32) * 32;
    final qB = (p[2] ~/ 32) * 32;
    final qKey = '${qR.toString().padLeft(3, '0')},${qG.toString().padLeft(3, '0')},${qB.toString().padLeft(3, '0')}';
    final oKey = '${p[0].toString().padLeft(3, '0')},${p[1].toString().padLeft(3, '0')},${p[2].toString().padLeft(3, '0')}';
    groups[qKey] ??= {};
    groups[qKey]![oKey] = (groups[qKey]![oKey] ?? 0) + 1;
  }
  int compressedCount = 0;
  for (final group in groups.values) {
    int maxCount = -1;
    String bestKey = '';
    for (final entry in group.entries) {
      if (entry.value > maxCount) {
        maxCount = entry.value;
        bestKey = entry.key;
      } else if (entry.value == maxCount) {
        if (entry.key.compareTo(bestKey) < 0) {
          bestKey = entry.key;
        }
      }
    }
    compressedCount += maxCount;
  }
  return compressedCount / pixels.length;
}

