import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(int orbitMinutes, int visibleMinutes, int offsetMinutes, int stationCycleMinutes, int stationOpenMinutes, int missionMinutes) {
  int gcd(int a, int b) {
    while (b != 0) {
      final t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  final combined = (orbitMinutes ~/ gcd(orbitMinutes, stationCycleMinutes)) * stationCycleMinutes;

  double overlapInCycle = 0;
  for (int s = offsetMinutes; s < combined; s += orbitMinutes) {
    final sEnd = s + visibleMinutes;
    final firstStation = (s ~/ stationCycleMinutes) * stationCycleMinutes;
    for (int g = firstStation; g < sEnd; g += stationCycleMinutes) {
      final gEnd = g + stationOpenMinutes;
      final ol = (sEnd < gEnd ? sEnd : gEnd) - (s > g ? s : g);
      if (ol > 0) overlapInCycle += ol;
    }
  }

  final fullCycles = missionMinutes ~/ combined;
  final remainder = missionMinutes % combined;
  double total = overlapInCycle * fullCycles;

  for (int s = offsetMinutes; s < remainder; s += orbitMinutes) {
    final sEnd = s + visibleMinutes;
    final firstStation = (s ~/ stationCycleMinutes) * stationCycleMinutes;
    for (int g = firstStation; g < sEnd; g += stationCycleMinutes) {
      final gEnd = g + stationOpenMinutes;
      final ol = (sEnd < gEnd ? sEnd : gEnd) - (s > g ? s : g);
      if (ol > 0) total += ol;
    }
  }

  return total;
}

