import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(String chart) {
  Map<String, int> result = {};
  if (chart.trim().isEmpty) {
    return result;
  }

  for (String rawSection in chart.split('|')) {
    int colonIndex = rawSection.indexOf(':');
    if (colonIndex <= 0) {
      continue;
    }

    String sectionName = rawSection.substring(0, colonIndex).trim();
    String seatsPart = rawSection.substring(colonIndex + 1);
    Map<String, String> latestStatus = {};

    for (String rawToken in seatsPart.split(',')) {
      String token = rawToken.trim();
      if (token.length < 3) {
        continue;
      }

      String status = token.substring(token.length - 1);
      if (status != 'O' && status != 'R' && status != 'B') {
        continue;
      }

      String seatId = token.substring(0, token.length - 1);
      bool seenDigit = false;
      bool valid = true;

      for (int i = 0; i < seatId.length; i++) {
        String ch = seatId[i];
        bool isDigit = ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57;
        bool isLetter = ch.codeUnitAt(0) >= 65 && ch.codeUnitAt(0) <= 90;

        if (isDigit) {
          seenDigit = true;
        } else if (!isLetter || seenDigit) {
          valid = false;
          break;
        }
      }

      if (valid && seenDigit) {
        latestStatus[seatId] = status;
      }
    }

    int openCount = 0;
    for (String status in latestStatus.values) {
      if (status == 'O') {
        openCount++;
      }
    }

    result[sectionName] = openCount;
  }

  return result;
}

