import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> pixels, int k) {
  int n = pixels.length ~/ 3;
  int totalPairs = n * (n - 1) ~/ 2;
  if (pixels.length % 3 != 0 || n < 2 || k < 1 || k > totalPairs) {
    return [-1, -1];
  }

  int chromaDist(int a, int b) {
    return (pixels[a * 3] - pixels[b * 3]).abs() +
        (pixels[a * 3 + 1] - pixels[b * 3 + 1]).abs() +
        (pixels[a * 3 + 2] - pixels[b * 3 + 2]).abs();
  }

  int countLe(int t) {
    int c = 0;
    for (int i = 0; i < n; i++) {
      for (int j = i + 1; j < n; j++) {
        if (chromaDist(i, j) <= t) c++;
      }
    }
    return c;
  }

  int countLt(int t) {
    int c = 0;
    for (int i = 0; i < n; i++) {
      for (int j = i + 1; j < n; j++) {
        if (chromaDist(i, j) < t) c++;
      }
    }
    return c;
  }

  int lo = 0, hi = 765;
  while (lo < hi) {
    int mid = (lo + hi) ~/ 2;
    if (countLe(mid) >= k) {
      hi = mid;
    } else {
      lo = mid + 1;
    }
  }

  int kthDist = lo;
  int eq = countLe(kthDist) - countLt(kthDist);
  return [kthDist, eq];
}

