List<int> fn0(String dna) {
  if (dna.isEmpty) return [];
  const Map<String, int> baseMap = {'A': 0, 'C': 1, 'G': 2, 'T': 3};
  List<int> output = [];
  int checksum = 0;
  int i = 0;
  while (i < dna.length) {
    String base = dna[i];
    if (!baseMap.containsKey(base)) {
      throw ArgumentError('Invalid DNA base: $base');
    }
    int baseVal = baseMap[base]!;
    int runLength = 1;
    i++;
    while (i < dna.length && dna[i] == base) {
      runLength++;
      i++;
    }
    int remaining = runLength;
    while (remaining >= 128) {
      output.add((remaining & 0x7F) | 0x80);
      remaining >>= 7;
    }
    output.add(remaining);
    output.add(baseVal);
    checksum = (checksum + baseVal * runLength) & 0xFF;
  }
  output.add(checksum);
  return output;
}

