import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<String> logLines, int totalDays) {
  int limit = totalDays * 1440;
  if (limit <= 0) {
    return 0;
  }

  List<List<int>> intervals = [];

  for (String line in logLines) {
    List<String> parts = line.split(' ');
    if (parts.length != 2) {
      continue;
    }

    int day = int.parse(parts[0]);
    List<String> times = parts[1].split('-');
    if (times.length != 2) {
      continue;
    }

    List<String> startParts = times[0].split(':');
    List<String> endParts = times[1].split(':');

    int startMinute = int.parse(startParts[0]) * 60 + int.parse(startParts[1]);
    int endMinute = int.parse(endParts[0]) * 60 + int.parse(endParts[1]);

    int start = day * 1440 + startMinute;
    int end = day * 1440 + endMinute;

    if (endMinute < startMinute) {
      end += 1440;
    }

    if (end <= 0 || start >= limit) {
      continue;
    }

    if (start < 0) {
      start = 0;
    }
    if (end > limit) {
      end = limit;
    }

    if (start < end) {
      intervals.add([start, end]);
    }
  }

  if (intervals.isEmpty) {
    return limit;
  }

  intervals.sort((a, b) => a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);

  int longest = intervals[0][0];
  int currentStart = intervals[0][0];
  int currentEnd = intervals[0][1];

  for (int i = 1; i < intervals.length; i++) {
    int nextStart = intervals[i][0];
    int nextEnd = intervals[i][1];

    if (nextStart <= currentEnd) {
      if (nextEnd > currentEnd) {
        currentEnd = nextEnd;
      }
    } else {
      int gap = nextStart - currentEnd;
      if (gap > longest) {
        longest = gap;
      }
      currentStart = nextStart;
      currentEnd = nextEnd;
    }
  }

  int tailGap = limit - currentEnd;
  if (tailGap > longest) {
    longest = tailGap;
  }

  return longest;
}

