import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<String> instructions) {
  List<Map<String, int>> stack = [{}];
  for (String inst in instructions) {
    if (inst == 'push') {
      stack.add({});
    } else if (inst.startsWith('add:')) {
      List<String> parts = inst.split(':');
      String ingredient = parts[1];
      int amount = int.parse(parts[2]);
      stack.last[ingredient] = (stack.last[ingredient] ?? 0) + amount;
    } else if (inst.startsWith('fold:')) {
      int multiplier = int.parse(inst.substring(5));
      Map<String, int> top = stack.removeLast();
      if (stack.isEmpty) {
        stack.add({});
      }
      top.forEach((key, value) {
        stack.last[key] = (stack.last[key] ?? 0) + value * multiplier;
      });
    } else if (inst.startsWith('scale:')) {
      int factor = int.parse(inst.substring(6));
      Map<String, int> scaled = {};
      stack.last.forEach((key, value) {
        scaled[key] = value * factor;
      });
      stack[stack.length - 1] = scaled;
    }
  }
  while (stack.length > 1) {
    Map<String, int> top = stack.removeLast();
    top.forEach((key, value) {
      stack.last[key] = (stack.last[key] ?? 0) + value;
    });
  }
  return stack.first;
}

