bool fn0(String symbols) {
  if (symbols.isEmpty) return false;
  int i = 0;
  int len = symbols.length;
  int balance = 0;
  int prevRun = 0;
  String prevChar = '';
  while (i < len) {
    String ch = symbols[i];
    if (ch != '.' && ch != '-' && ch != ' ') return false;
    if (ch == ' ') {
      i++;
      continue;
    }
    int j = i;
    while (j < len && symbols[j] == ch) {
      j++;
    }
    int run = j - i;
    if (run > 4 || run < 1) return false;
    if (prevChar == ch && prevRun > 0) return false;
    int weight = (ch == '-') ? 2 : 1;
    balance += weight * run - prevRun;
    prevRun = run;
    prevChar = ch;
    i = j;
  }
  return balance == 0 && prevRun > 0;
}

