import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<String> schedules) {
  const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  final Map<String, List<List<int>>> events = {};
  final Map<String, int> result = {};

  int toMinutes(String time) {
    final parts = time.split(':');
    return int.parse(parts[0]) * 60 + int.parse(parts[1]);
  }

  void addInterval(String zone, String day, int start, int end, int temp) {
    final key = '$zone|$day';
    events.putIfAbsent(key, () => []);
    events[key]!.add([start, 1, temp]);
    events[key]!.add([end, -1, temp]);
  }

  for (final schedule in schedules) {
    final parts = schedule.split('|');
    final zone = parts[0];
    final day = parts[1];
    final range = parts[2].split('-');
    final start = toMinutes(range[0]);
    final end = toMinutes(range[1]);
    final temp = int.parse(parts[3]);
    result.putIfAbsent(zone, () => 0);

    if (end > start) {
      addInterval(zone, day, start, end, temp);
    } else {
      addInterval(zone, day, start, 1440, temp);
      final nextDay = days[(days.indexOf(day) + 1) % 7];
      addInterval(zone, nextDay, 0, end, temp);
    }
  }

  for (final entry in events.entries) {
    final zone = entry.key.split('|')[0];
    final list = entry.value;
    list.sort((a, b) {
      if (a[0] != b[0]) return a[0] - b[0];
      return a[1] - b[1];
    });

    final Map<int, int> activeTemps = {};
    int previousMinute = list[0][0];
    int index = 0;

    while (index < list.length) {
      final minute = list[index][0];
      if (activeTemps.length > 1) {
        result[zone] = result[zone]! + (minute - previousMinute);
      }

      while (index < list.length && list[index][0] == minute) {
        final delta = list[index][1];
        final temp = list[index][2];
        activeTemps[temp] = (activeTemps[temp] ?? 0) + delta;
        if (activeTemps[temp] == 0) {
          activeTemps.remove(temp);
        }
        index++;
      }

      previousMinute = minute;
    }
  }

  return result;
}

