  List<int> stack = [];
  for (int op in operations) {
    if (op >= 0) {
      stack.add(op % 256);
    } else if (stack.isNotEmpty) {
      int last = stack.removeLast();
      if (stack.isNotEmpty) {
        stack[stack.length - 1] = (stack.last + last) ~/ 2;
      }
    }
  }
  if (stack.isEmpty) return 0;
  int result = 0;
  for (int v in stack) {
    result = (result + v) % 256;
  }
  return result;
}

