Map<String, int> fn0(List<int> editCosts, int k) {
  if (editCosts.isEmpty || k < 1 || k > editCosts.length) {
    return {'kthSmallestCost': -1, 'totalElementsLE': 0};
  }
  int low = editCosts[0];
  int high = editCosts[0];
  for (int i = 1; i < editCosts.length; i++) {
    if (editCosts[i] < low) low = editCosts[i];
    if (editCosts[i] > high) high = editCosts[i];
  }
  int ans = low;
  while (low <= high) {
    int mid = low + (high - low) ~/ 2;
    int count = 0;
    for (int cost in editCosts) {
      if (cost <= mid) count++;
    }
    if (count >= k) {
      ans = mid;
      high = mid - 1;
    } else {
      low = mid + 1;
    }
  }
  int finalCount = 0;
  for (int cost in editCosts) {
    if (cost <= ans) finalCount++;
  }
  return {'kthSmallestCost': ans, 'totalElementsLE': finalCount};
}

