@pragma('vm:entry-point')
bool fn0(List<String> sequence) {
  var stack = <String>[];
  int aCount = 0;
  int bCount = 0;
  for (String event in sequence) {
    if (event == "voteA") {
      stack.add("A");
      aCount++;
    } else if (event == "voteB") {
      stack.add("B");
      bCount++;
    } else if (event == "pair") {
      if (stack.length < 2) return false;
      String s2 = stack.removeLast();
      String s1 = stack.removeLast();
      if (!(s1 == "A" && s2 == "B") && !(s1 == "B" && s2 == "A")) return false;
      if (s1 == "A") aCount--; else bCount--;
      if (s2 == "A") aCount--; else bCount--;
    } else if (event == "undo") {
      if (stack.isEmpty) return false;
      String top = stack.removeLast();
      if (top == "A") aCount--; else bCount--;
    }
    if (aCount < 0 || bCount < 0) return false;
  }
  return stack.isEmpty && aCount == 0 && bCount == 0;
}

