import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> departures, int stops, int minGap) {
  int n = departures.length;
  if (stops <= 0 || n < stops) return -1.0;
  if (stops == 1) return 0.0;
  double transferCost = 2.5;
  List<List<double>> dp = List.generate(
      n, (_) => List.filled(stops + 1, double.negativeInfinity));
  for (int i = 0; i < n; i++) {
    dp[i][1] = departures[i].toDouble();
  }
  for (int j = 2; j <= stops; j++) {
    for (int i = 0; i < n; i++) {
      for (int p = 0; p < i; p++) {
        if (departures[i] - departures[p] >= minGap &&
            dp[p][j - 1] != double.negativeInfinity &&
            dp[p][j - 1] > dp[i][j]) {
          dp[i][j] = dp[p][j - 1];
        }
      }
    }
  }
  double bestCost = double.infinity;
  for (int i = 0; i < n; i++) {
    if (dp[i][stops] != double.negativeInfinity) {
      double cost = departures[i] - dp[i][stops] + (stops - 1) * transferCost;
      if (cost < bestCost) bestCost = cost;
    }
  }
  return bestCost == double.infinity ? -1.0 : bestCost;
}

