@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> rowCapacities) {
  int rows = rowCapacities.length;
  List<int> globalStart = List.filled(rows, 0);
  int sum = 0;
  for (int r = 0; r < rows; r++) {
    globalStart[r] = sum;
    sum += rowCapacities[r];
  }

  List<List<int>> rowOrders = List.generate(rows, (r) {
    int n = rowCapacities[r];
    if (n == 0) return [];
    List<int> order = [];
    if (n % 2 == 1) {
      int mid = n ~/ 2;
      order.add(mid);
      for (int offset = 1; offset <= mid; offset++) {
        if (mid - offset >= 0) order.add(mid - offset);
        if (mid + offset < n) order.add(mid + offset);
      }
    } else {
      int leftCenter = n ~/ 2 - 1;
      order.add(leftCenter);
      for (int offset = 1; offset <= n ~/ 2; offset++) {
        if (leftCenter + offset < n) order.add(leftCenter + offset);
        if (leftCenter - offset >= 0) order.add(leftCenter - offset);
      }
    }
    return order;
  });

  List<int> result = [];
  List<int> pointers = List.filled(rows, 0);
  bool hasMore = true;
  while (hasMore) {
    hasMore = false;
    for (int r = 0; r < rows; r++) {
      if (pointers[r] < rowOrders[r].length) {
        hasMore = true;
        int localSeat = rowOrders[r][pointers[r]];
        int globalSeat = globalStart[r] + localSeat;
        result.add(globalSeat);
        pointers[r]++;
      }
    }
  }
  return result;
}

