String fn0(List<List<int>> transactions, int startDay, int endDay) {
  if (startDay > endDay) return "Invalid range";

  List<List<int>> sorted = List.from(transactions);
  sorted.sort((a, b) => a[0].compareTo(b[0]));

  List<String> periods = [];
  int runStart = -1;

  for (int day = startDay; day <= endDay; day++) {
    int balance = 0;
    for (var tx in sorted) {
      if (tx[0] <= day) {
        balance += tx[1];
      } else {
        break;
      }
    }
    if (balance < 0) {
      if (runStart == -1) {
        runStart = day;
      }
    } else {
      if (runStart != -1) {
        periods.add(runStart == day - 1 ? "$runStart" : "$runStart-${day - 1}");
        runStart = -1;
      }
    }
  }

  if (runStart != -1) {
    periods.add(runStart == endDay ? "$runStart" : "$runStart-$endDay");
  }

  if (periods.isEmpty) return "Balance healthy";
  return "Overdrawn: days ${periods.join(", ")}";
}

