bool fn0(List<List<int>> cells, List<int> exitCell) {
  if (cells.isEmpty) return false;

  List<List<int>> sortedCells = cells.map((c) => [c[0], c[1]]).toList();

  sortedCells.sort((a, b) {
    int distA = (a[0] - exitCell[0]).abs() + (a[1] - exitCell[1]).abs();
    int distB = (b[0] - exitCell[0]).abs() + (b[1] - exitCell[1]).abs();
    if (distA != distB) {
      return distA.compareTo(distB);
    }
    if (a[0] != b[0]) {
      return a[0].compareTo(b[0]);
    }
    return a[1].compareTo(b[1]);
  });

  for (int i = 0; i < sortedCells.length - 1; i++) {
    int rowDiff = (sortedCells[i][0] - sortedCells[i+1][0]).abs();
    int colDiff = (sortedCells[i][1] - sortedCells[i+1][1]).abs();
    if (rowDiff + colDiff != 1) {
      return false;
    }
  }

  return true;
}

