double fn0(String manifest) {



  double total = 0.0;
  for (final entry in manifest.split(';')) {
    final trimmed = entry.trim();
    if (trimmed.isEmpty) continue;
    final colon = trimmed.indexOf(':');
    if (colon <= 0) continue;
    var label = trimmed.substring(0, colon);
    final spec = trimmed.substring(colon + 1);
    bool fragile = false;
    if (label.startsWith('!')) {
      fragile = true;
      label = label.substring(1);
    }
    if (label.isEmpty) continue;
    final at = spec.indexOf('@');
    if (at <= 0 || at == spec.length - 1) continue;
    final qty = int.tryParse(spec.substring(0, at));
    final weight = double.tryParse(spec.substring(at + 1));
    if (qty == null || weight == null || qty < 0 || weight < 0) continue;
    double subtotal = qty * weight;
    if (fragile) subtotal *= 1.5;
    total += subtotal;
  }
  return total;
}

