bool fn0(List<String> rows, int targetWidth) {
  if (rows.isEmpty) return false;
  final int n = rows.length;
  int getWidth(String row) {
    int count = 0;
    for (int i = 0; i < row.length; i++) {
      if (row[i] != ' ') count++;
    }
    return count;
  }
  int lo = 0, hi = n - 1;
  while (lo < hi) {
    final int mid = lo + (hi - lo) ~/ 2;
    if (getWidth(rows[mid]) < getWidth(rows[mid + 1])) lo = mid + 1;
    else hi = mid;
  }
  final int peakIdx = lo;
  lo = 0; hi = peakIdx;
  while (lo <= hi) {
    final int mid = lo + (hi - lo) ~/ 2;
    final int w = getWidth(rows[mid]);
    if (w == targetWidth) return true;
    if (w < targetWidth) lo = mid + 1; else hi = mid - 1;
  }
  lo = peakIdx + 1; hi = n - 1;
  while (lo <= hi) {
    final int mid = lo + (hi - lo) ~/ 2;
    final int w = getWidth(rows[mid]);
    if (w == targetWidth) return true;
    if (w > targetWidth) lo = mid + 1; else hi = mid - 1;
  }
  return false;
}

