Set<int> fn0(List<int> hashes, int numBuckets, int k) {

  if (numBuckets <= 0 || k <= 0 || k > numBuckets) return {};


  List<int> counts = List.filled(numBuckets, 0);
  for (int h in hashes) {
    int bucket = ((h % numBuckets) + numBuckets) % numBuckets;
    counts[bucket]++;
  }



  int lo = 0, hi = hashes.length;
  while (lo < hi) {
    int mid = lo + (hi - lo + 1) ~/ 2; 
    int aboveOrEqual = 0;
    for (int c in counts) {
      if (c >= mid) aboveOrEqual++;
    }
    if (aboveOrEqual >= k) {
      lo = mid; 
    } else {
