String fn0(List<Map<String, Object>> entries) {
  if (entries.isEmpty) return '';
  final sorted = List<Map<String, Object>>.from(entries)
    ..sort((a, b) => (a['order'] as int).compareTo(b['order'] as int));
  final Map<String, List<double>> byAccount = {};
  for (final e in sorted) {
    final acc = e['account'] as String;
    final amt = e['amount'] as double;
    byAccount.putIfAbsent(acc, () => <double>[]).add(amt);
  }
  final Map<String, double> drawdowns = {};
  for (final entry in byAccount.entries) {
    final acc = entry.key;
    final amounts = entry.value;
    double balance = 0.0;
    double peak = 0.0;
    double maxDd = 0.0;
    for (final amt in amounts) {
      balance += amt;
      if (balance > peak) peak = balance;
      final dd = peak - balance;
      if (dd > maxDd) maxDd = dd;
    }
    drawdowns[acc] = maxDd;
  }
  final keys = drawdowns.keys.toList()..sort();
  return keys.map((k) => '$k:${drawdowns[k]}').join(', ');
}

