List<int> fn0(String password) {
  if (password.length < 8) return [];
  bool hasUpper = false, hasLower = false, hasDigit = false, hasSpecial = false;
  int consecutive = 1;
  for (int i = 0; i < password.length; i++) {
    int code = password.codeUnitAt(i);
    if (code >= 65 && code <= 90) hasUpper = true;
    else if (code >= 97 && code <= 122) hasLower = true;
    else if (code >= 48 && code <= 57) hasDigit = true;
    else hasSpecial = true;
    if (i > 0 && password.codeUnitAt(i) == password.codeUnitAt(i - 1)) {
      consecutive++;
      if (consecutive >= 3) return [];
    } else {
      consecutive = 1;
    }
  }
  if (!(hasUpper && hasLower && hasDigit && hasSpecial)) return [];

  List<int> shiftedCodes = [];
  for (int i = 0; i < password.length; i++) {
    int code = password.codeUnitAt(i);
    if (code >= 65 && code <= 90) {
      code = (code - 65 + 5) % 26 + 65;
    } else if (code >= 97 && code <= 122) {
      code = (code - 97 + 5) % 26 + 97;
    }
    shiftedCodes.add(code);
  }

  List<int> result = [];
  int runLength = 1;
  for (int i = 0; i < shiftedCodes.length; i++) {
    if (i + 1 < shiftedCodes.length && shiftedCodes[i] == shiftedCodes[i + 1]) {
      runLength++;
    } else {
      result.add(runLength);
      result.add(shiftedCodes[i]);
      runLength = 1;
    }
  }
  return result;
}

