@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> hashes, int bucketCount, int windowSize) {
  if (bucketCount <= 0 || windowSize <= 0 || hashes.length < windowSize) {
    return <int>[];
  }

  List<int> buckets = <int>[];
  for (int value in hashes) {
    int bucket = value % bucketCount;
    if (bucket < 0) {
      bucket += bucketCount;
    }
    buckets.add(bucket);
  }

  Map<int, int> windowFreq = <int, int>{};
  Map<int, int> scores = <int, int>{};

  for (int right = 0; right < buckets.length; right++) {
    int addBucket = buckets[right];
    windowFreq[addBucket] = (windowFreq[addBucket] ?? 0) + 1;

    if (right >= windowSize) {
      int removeBucket = buckets[right - windowSize];
      int nextCount = (windowFreq[removeBucket] ?? 0) - 1;
      if (nextCount == 0) {
        windowFreq.remove(removeBucket);
      } else {
        windowFreq[removeBucket] = nextCount;
      }
    }

    if (right >= windowSize - 1) {
      int maxFreq = 0;
      List<int> leaders = <int>[];

      windowFreq.forEach((int bucket, int count) {
        if (count > maxFreq) {
          maxFreq = count;
          leaders = <int>[bucket];
        } else if (count == maxFreq) {
          leaders.add(bucket);
        }
      });

      if (leaders.length == 1) {
        int winner = leaders[0];
        scores[winner] = (scores[winner] ?? 0) + 1;
      } else {
        for (int bucket in leaders) {
          int current = scores[bucket] ?? 0;
          if (current > 0) {
            scores[bucket] = current - 1;
          }
        }
      }
    }
  }

  int bestScore = 0;
  scores.forEach((int bucket, int score) {
    if (score > bestScore) {
      bestScore = score;
    }
  });

  if (bestScore == 0) {
    return <int>[];
  }

  List<int> result = <int>[];
  scores.forEach((int bucket, int score) {
    if (score == bestScore) {
      result.add(bucket);
    }
  });

  result.sort();
  return result;
}

