String fn0(int totalDays, List<int> startDays, List<int> durations, List<String> bins) {
  if (totalDays <= 0 ||
      startDays.length != durations.length ||
      durations.length != bins.length) {
    return 'none:0/0';
  }

  List<String> days = List.filled(totalDays, 'none');

  for (int i = 0; i < startDays.length; i++) {
    int start = startDays[i] % totalDays;
    int span = durations[i];

    if (span <= 0) {
      continue;
    }

    for (int d = 0; d < span; d++) {
      int index = (start + d) % totalDays;
      days[index] = bins[i];
    }
  }

  Map<String, int> totals = {};
  Map<String, int> bestSpans = {};

  for (String bin in days) {
    if (bin != 'none') {
      totals[bin] = (totals[bin] ?? 0) + 1;
    }
  }

  for (String bin in totals.keys) {
    int best = 0;
    int current = 0;

    for (int i = 0; i < totalDays * 2; i++) {
      if (days[i % totalDays] == bin) {
        current++;
        if (current > totalDays) {
          current = totalDays;
        }
        if (current > best) {
          best = current;
        }
      } else {
        current = 0;
      }
    }

    bestSpans[bin] = best;
  }

  String winner = 'none';
  int winnerSpan = 0;
  int winnerTotal = 0;

  for (String bin in bestSpans.keys) {
    int span = bestSpans[bin]!;
    int total = totals[bin]!;

    if (span > winnerSpan ||
        (span == winnerSpan && total > winnerTotal) ||
        (span == winnerSpan && total == winnerTotal &&
            (winner == 'none' || bin.compareTo(winner) < 0))) {
      winner = bin;
      winnerSpan = span;
      winnerTotal = total;
    }
  }

  return '$winner:$winnerSpan/$winnerTotal';
}

