@pragma('vm:entry-point')
int fn0(List<String> commands) {
  List<int> stack = [11]; 

  for (String cmd in commands) {
    if (cmd == 'UNDO') {
      if (stack.length > 1) {
        stack.removeLast();
      }
    } else if (cmd.length == 2) {
      int f = cmd.codeUnitAt(0) - 96; 
      int r = int.parse(cmd[1]);
      if (f < 1 || f > 8 || r < 1 || r > 8) continue;
      int cur = stack.last;
      int curF = cur ~/ 10;
      int curR = cur % 10;
      if ((f == curF || r == curR) && (f != curF || r != curR)) {
        stack.add(f * 10 + r);
      }
    }
  }

  int totalDist = 0;
  for (int i = 1; i < stack.length; i++) {
    int prevF = stack[i - 1] ~/ 10;
    int prevR = stack[i - 1] % 10;
    int curF = stack[i] ~/ 10;
    int curR = stack[i] % 10;
    totalDist += (curF - prevF).abs() + (curR - prevR).abs();
  }
  return totalDist;
}

