Map<String, int> fn0(String amounts) {
  Map<String, int> result = {};
  int totalChecksum = 0;

  if (amounts.trim().isEmpty) {
    result["checksum"] = 0;
    return result;
  }

  List<String> tokens = amounts.split(',');
  for (String token in tokens) {
    String trimmed = token.trim();
    if (trimmed.isEmpty) continue;

    double value = double.parse(trimmed);
    double scaled = value * 100.0;
    double absScaled = scaled.abs();

    int intPart = absScaled.floor();
    double fracPart = absScaled - intPart;

    int resultAbs;
    if (fracPart < 0.5) {
      resultAbs = intPart;
    } else if (fracPart > 0.5) {
      resultAbs = intPart + 1;
    } else {
      resultAbs = (intPart % 2 == 0) ? intPart : intPart + 1;
    }

    int cents = scaled < 0 ? -resultAbs : resultAbs;
    totalChecksum = (totalChecksum + cents) % 1000;

    String key = cents >= 0 
        ? "+${cents.toString().padLeft(3, '0')}" 
        : "-${(-cents).toString().padLeft(3, '0')}";

    result[key] = (result[key] ?? 0) + 1;
  }

  int finalChecksum = totalChecksum < 0 ? totalChecksum + 1000 : totalChecksum;
  result["checksum"] = finalChecksum;

  return result;
}

