String fn0(String dna) {
  if (dna.isEmpty) return "";

  List<String> alphabet = ['A','C','G','T'];
  const map = ['A','C','G','T'];
  StringBuffer mtf = StringBuffer();
  for (int i = 0; i < dna.length; i++) {
    String base = dna[i];
    int idx = alphabet.indexOf(base);
    mtf.write(map[idx]);
    alphabet.removeAt(idx);
    alphabet.insert(0, base);
  }

  String mtfStr = mtf.toString();
  StringBuffer result = StringBuffer();
  int n = mtfStr.length;
  int i = 0;
  while (i < n) {
    String currentBase = mtfStr[i];
    int runStart = i;
    while (i < n && mtfStr[i] == currentBase) {
      i++;
    }
    int runLength = i - runStart;
    while (runLength > 9) {
      result.write(currentBase);
      result.write('9');
      runLength -= 9;
    }
    if (runLength > 0) {
      result.write(currentBase);
      result.write(runLength.toString());
    }
  }
  return result.toString();
}

