@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<List<int>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return 0;
  int rows = grid.length;
  int cols = grid[0].length;
  List<List<int>> dp = List.generate(rows, (_) => List<int>.filled(cols, 0));
  for (int r = 0; r < rows; r++) {
    dp[r][0] = grid[r][0];
  }
  for (int c = 1; c < cols; c++) {
    for (int r = 0; r < rows; r++) {
      int best = dp[r][c - 1];
      if (r > 0 && dp[r - 1][c - 1] > best) best = dp[r - 1][c - 1];
      if (r < rows - 1 && dp[r + 1][c - 1] > best) best = dp[r + 1][c - 1];
      dp[r][c] = grid[r][c] + best;
    }
  }
  int ans = dp[0][cols - 1];
  for (int r = 1; r < rows; r++) {
    if (dp[r][cols - 1] > ans) ans = dp[r][cols - 1];
  }
  return ans;
}

