@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<String> board, int initialEnergy, int targetEnergy) {
  if (board.isEmpty || board[0].isEmpty) {
    return false;
  }

  int rows = board.length;
  int cols = board[0].length;

  if (board[0][0] == '#' || board[rows - 1][cols - 1] == '#') {
    return false;
  }

  List<List<Set<int>>> dp = List.generate(
    rows,
    (_) => List.generate(cols, (_) => <int>{}),
  );

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      String cell = board[r][c];

      if (cell == '#') {
        continue;
      }

      int value = cell.codeUnitAt(0) - 48;
      int delta = ((r + c) % 2 == 0) ? value : -value;

      Set<int> incoming = <int>{};

      if (r == 0 && c == 0) {
        incoming.add(initialEnergy);
      }

      if (r > 0) {
        incoming.addAll(dp[r - 1][c]);
      }

      if (c > 0) {
        incoming.addAll(dp[r][c - 1]);
      }

      for (int energy in incoming) {
        int nextEnergy = energy + delta;

        if (nextEnergy >= 0) {
          dp[r][c].add(nextEnergy);
        }
      }
    }
  }

  return dp[rows - 1][cols - 1].contains(targetEnergy);
}

