int fn0(List<List<bool>> modules) {
  if (modules.isEmpty) return 0;
  final height = modules.length;
  final width = modules[0].length;
  if (height < 2 || width < 2) return 0;

  final patternIds = <int>[];
  for (int r = 0; r < height - 1; r += 2) {
    for (int c = 0; c < width - 1; c += 2) {
      int id = 0;
      if (modules[r][c]) id |= 8;         
      if (modules[r][c + 1]) id |= 4;     
      if (modules[r + 1][c]) id |= 2;     
      if (modules[r + 1][c + 1]) id |= 1; 
      patternIds.add(id);
    }
  }

  final evenParity = <int>[];
  final oddParity = <int>[];
  for (int id in patternIds) {
    int count = 0;
    int v = id;
    while (v > 0) {
      count += v & 1;
      v >>= 1;
    }
    if (count % 2 == 0) {
      evenParity.add(id);
    } else {
      oddParity.add(id);
    }
  }

  final uniqueEven = evenParity.toSet();
  final uniqueOdd = oddParity.toSet();

  return [uniqueEven, uniqueOdd].fold(0, (acc, set) => acc + (set == uniqueEven ? set.length : -set.length));
}

