  if (chargeCycles.isEmpty || chargeCycles[0].isEmpty) return [];
  int rows = chargeCycles.length;
  int cols = chargeCycles[0].length;
  List<int> result = [];
  int top = 0, bottom = rows - 1, left = 0, right = cols - 1;
  while (top <= bottom && left <= right) {
    for (int j = left; j <= right; j++) {
      if (chargeCycles[top][j] >= degradationThreshold) result.add(chargeCycles[top][j]);
    }
    top++;
    for (int i = top; i <= bottom; i++) {
      if (chargeCycles[i][right] >= degradationThreshold) result.add(chargeCycles[i][right]);
    }
    right--;
    if (top <= bottom) {
      for (int j = right; j >= left; j--) {
        if (chargeCycles[bottom][j] >= degradationThreshold) result.add(chargeCycles[bottom][j]);
      }
      bottom--;
    }
    if (left <= right) {
      for (int i = bottom; i >= top; i--) {
        if (chargeCycles[i][left] >= degradationThreshold) result.add(chargeCycles[i][left]);
      }
      left++;
    }
  }
  return result;
}

