Set<int> fn0(String word, String suggestion) {
  List<int> edits = [];
  int len = word.length < suggestion.length ? word.length : suggestion.length;
  for (int i = 0; i < len; i++) {
    if (word[i] != suggestion[i]) {
      edits.add(i);
    }
  }
  if (word.length != suggestion.length) {
    int start = len;
    while (start < (word.length > suggestion.length ? word.length : suggestion.length)) {
      edits.add(start);
      start++;
    }
  }
  edits.sort((int a, int b) {
    int distA = (a - len).abs();
    int distB = (b - len).abs();
    if (distA != distB) return distA.compareTo(distB);
    return word.codeUnitAt(a).compareTo(word.codeUnitAt(b));
  });
  return edits.toSet();
}

