List<int> fn0(int totalQuantity, int vendorId) {
  if (totalQuantity <= 1) return [];
  List<int> validSizes = [];

  int gcd(int a, int b) {
    a = a < 0 ? -a : a;
    b = b < 0 ? -b : b;
    while (b != 0) {
      int temp = b;
      b = a % b;
      a = temp;
    }
    return a;
  }

  for (int i = 1; i * i <= totalQuantity; i++) {
    if (totalQuantity % i == 0) {
      int j = totalQuantity ~/ i;
      if (i > 1 && gcd(i, vendorId) == 1) {
        validSizes.add(i);
      }
      if (j != i && j > 1 && gcd(j, vendorId) == 1) {
        validSizes.add(j);
      }
    }
  }

  validSizes.sort();
  return validSizes;
}

