import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> logs, int batchSize, int cooldownLength) {
  int n = logs.length;
  if (n < 2 * batchSize + cooldownLength) return [];

  int numWindows = n - batchSize + 1;
  List<int> windowSum = List.filled(numWindows, 0);
  int currentSum = 0;
  for (int i = 0; i < batchSize; i++) currentSum += logs[i];
  windowSum[0] = currentSum;

  for (int i = 1; i < numWindows; i++) {
    currentSum += logs[i + batchSize - 1] - logs[i - 1];
    windowSum[i] = currentSum;
  }

  int j = batchSize + cooldownLength;
  int maxLeftSum = windowSum[0];
  int currentBestI = 0;
  int bestSum = maxLeftSum + windowSum[j];
  int bestI = 0;
  int bestJ = j;

  for (int k = j + 1; k < numWindows; k++) {
    int validI = k - batchSize - cooldownLength;
    if (windowSum[validI] > maxLeftSum) {
      maxLeftSum = windowSum[validI];
      currentBestI = validI;
    }
    int candSum = maxLeftSum + windowSum[k];
    if (candSum > bestSum) {
      bestSum = candSum;
      bestI = currentBestI;
      bestJ = k;
    } else if (candSum == bestSum) {
      if (currentBestI < bestI || (currentBestI == bestI && k < bestJ)) {
        bestI = currentBestI;
        bestJ = k;
      }
    }
  }
  return [bestI, bestJ];
}

