List<String> fn0(List<double> quantities, double maxSum) {
  if (quantities.isEmpty) return [];
  int left = 0;
  double currentSum = 0.0;
  int bestStart = 0;
  int bestLen = 0;
  for (int right = 0; right < quantities.length; right++) {
    currentSum += quantities[right];
    while (currentSum > maxSum && left <= right) {
      currentSum -= quantities[left];
      left++;
    }
    int len = right - left + 1;
    if (len > bestLen) {
      bestLen = len;
      bestStart = left;
    }
  }
  if (bestLen == 0) return [];
  List<String> result = [];
  for (int i = bestStart; i < bestStart + bestLen; i++) {
    double scaled = quantities[i] * 2.0;
    result.add(scaled.toString());
  }
  return result;
}

