List<String> fn0(List<int> playlistMasks, List<String> tracks, int seed) {
  if (tracks.isEmpty) {
    return <String>[];
  }

  int popcount(int value) {
    int count = 0;
    while (value != 0) {
      count += value & 1;
      value = value >> 1;
    }
    return count;
  }

  List<String> result = <String>[];
  int state = seed & 31;

  for (int mask in playlistMasks) {
    int value = mask & 0xffffffff;
    int rotated;

    if (state == 0) {
      rotated = value;
    } else {
      rotated = (((value << state) & 0xffffffff) |
              (value >> (32 - state))) &
          0xffffffff;
    }

    int energy = popcount(rotated & 0x3ff);
    int mood = popcount((rotated >> 10) & 0x3ff);
    int index =
        (((rotated >> 20) ^ energy ^ (mood << 1)) % tracks.length);

    List<String> tags = <String>[];
    tags.add(energy % 2 == 0 ? 'sync' : 'solo');
    tags.add(mood >= 5 ? 'night' : 'day');

    if (((rotated >> 30) & 1) == 1) {
      tags.add('live');
    }

    int score = (energy << 1) + mood;
    result.add('${tracks[index]}|${tags.join('&')}|$score');

    state = (state + score + (rotated & 15)) & 31;
  }

  return result;
}

