bool fn0(List<List<int>> rounds, int streak) {


  if (streak <= 0) return true;
  int current = 0;
  int lastFace = -1;
  for (final round in rounds) {
    final counts = <int, int>{};
    for (final die in round) {
      counts[die] = (counts[die] ?? 0) + 1;
    }
    int bestFace = -1;
    int bestCount = 0;
    bool tie = false;
    counts.forEach((face, c) {
      if (c > bestCount) {
        bestCount = c;
        bestFace = face;
        tie = false;
      } else if (c == bestCount) {
        tie = true;
      }
    });
    if (bestFace == -1 || tie) {
      current = 0;
      lastFace = -1;
    } else if (bestFace == lastFace) {
      current += 1;
    } else {
      lastFace = bestFace;
      current = 1;
    }
    if (current >= streak) return true;
  }
  return false;
}

