@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(int logTeams, int winMask) {
  if (logTeams < 1 || logTeams > 30) return false;
  int n = 1 << logTeams;
  if (winMask < 0 || winMask >= (1 << n)) return false;
  int currentWinners = winMask;
  int expectedWinners = n >> 1;
  for (int round = 0; round < logTeams; round++) {
    int pop = 0;
    int temp = currentWinners;
    while (temp != 0) {
      pop += temp & 1;
      temp >>= 1;
    }
    if (pop != expectedWinners) return false;
    int nextWinners = 0;
    int step = 2 << round;
    for (int base = 0; base < n; base += step) {
      int half = step >> 1;
      int regionMask = ((1 << step) - 1) << base;
      int regionWinners = currentWinners & regionMask;
      int lowWin = regionWinners & ((1 << half) - 1);
      int highWin = regionWinners >> half;
      if (lowWin != 0 && highWin != 0) return false;
      if (lowWin != 0 || highWin != 0) {
        nextWinners |= (1 << (base >> (round + 1)));
      }
    }
    currentWinners = nextWinners;
    expectedWinners >>= 1;
  }
  return currentWinners == 1;
}

