bool fn0(List<List<double>> grid, double threshold) {
  if (grid.length <= 1) return true;
  List<List<double>> profiles = [];
  for (int r = 0; r < grid.length; r++) {
    List<double> row = grid[r];
    int count = 0, longestRun = 0, currentRun = 0, currentStart = -1, longestStart = row.length;
    double longestSum = 0.0, currentSum = 0.0;
    for (int c = 0; c < row.length; c++) {
      if (row[c] >= threshold) {
        count++;
        if (currentRun == 0) currentStart = c;
        currentRun++;
        currentSum += row[c];
      } else {
        if (currentRun > longestRun || (currentRun == longestRun && currentSum > longestSum) ||
            (currentRun == longestRun && currentSum == longestSum && currentStart < longestStart)) {
          longestRun = currentRun; longestSum = currentSum; longestStart = currentStart;
        }
        currentRun = 0; currentSum = 0.0;
      }
    }
    if (currentRun > longestRun || (currentRun == longestRun && currentSum > longestSum) ||
        (currentRun == longestRun && currentSum == longestSum && currentStart < longestStart)) {
      longestRun = currentRun; longestSum = currentSum; longestStart = currentStart;
    }
    if (longestRun == 0) longestStart = row.length;
    profiles.add([longestRun.toDouble(), longestSum, longestStart.toDouble(), count.toDouble()]);
  }
  for (int i = 0; i < profiles.length - 1; i++) {
    List<double> a = profiles[i], b = profiles[i + 1];
    if (a[0] < b[0]) return false;
    if (a[0] == b[0]) {
      if (a[1] < b[1]) return false;
      if (a[1] == b[1]) {
        if (a[2] > b[2]) return false;
        if (a[2] == b[2] && a[3] < b[3]) return false;
      }
    }
  }
  return true;
}

