import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<String> matches) {
  Map<String, int> scores = {};
  Map<String, int> losses = {};
  Map<String, Set<String>> defeatedOpponents = {};

  for (String match in matches) {
    List<String> parts = match.split('>');
    if (parts.length != 2) {
      continue;
    }

    String winner = parts[0].trim();
    String loser = parts[1].trim();

    if (winner.isEmpty || loser.isEmpty || winner == loser) {
      continue;
    }

    int winnerLosses = losses[winner] ?? 0;
    int loserLosses = losses[loser] ?? 0;

    if (winnerLosses >= 2 || loserLosses >= 2) {
      continue;
    }

    defeatedOpponents.putIfAbsent(winner, () => <String>{});
    defeatedOpponents.putIfAbsent(loser, () => <String>{});

    int bonus = defeatedOpponents[loser]!.length;
    int gained = 1 + bonus;

    losses[loser] = loserLosses + 1;
    defeatedOpponents[winner]!.add(loser);

    if (losses[loser] == 2) {
      gained += 2;
    }

    scores[winner] = (scores[winner] ?? 0) + gained;
  }

  Map<String, int> result = {};
  for (String player in scores.keys) {
    if (scores[player]! > 0) {
      result[player] = scores[player]!;
    }
  }

  return result;
}

