bool fn0(String chart) {
  if (chart.isEmpty) return true;
  final rows = chart.split(';');
  List<Set<int>> rowSeats = [];
  int? maxSeat;
  int? firstRowOrd;
  for (int i = 0; i < rows.length; i++) {
    final row = rows[i];
    if (row.isEmpty || row.length < 2) return false;
    final code = row.codeUnitAt(0);
    if (code < 65 || code > 90) return false;
    final rowOrd = code - 65;
    if (i == 0) {
      firstRowOrd = rowOrd;
    } else if (rowOrd != firstRowOrd! + i) {
      return false;
    }
    final seatPart = row.substring(1);
    if (seatPart.isEmpty) return false;
    final specs = seatPart.split(',');
    final Set<int> seats = {};
    for (final spec in specs) {
      if (spec.isEmpty) return false;
      final dashIdx = spec.indexOf('-');
      if (dashIdx == -1) {
        final num = int.tryParse(spec);
        if (num == null || num <= 0) return false;
        if (!seats.add(num)) return false;
      } else {
        if (dashIdx == 0 || dashIdx == spec.length - 1) return false;
        final start = int.tryParse(spec.substring(0, dashIdx));
        final end = int.tryParse(spec.substring(dashIdx + 1));
        if (start == null || end == null || start <= 0 || end <= 0) return false;
        if (start > end) return false;
        for (int s = start; s <= end; s++) {
          if (!seats.add(s)) return false;
        }
      }
    }
    rowSeats.add(seats);
    final rowMax = seats.reduce((a, b) => a > b ? a : b);
    if (maxSeat == null) {
      maxSeat = rowMax;
    } else if (maxSeat != rowMax) {
      return false;
    }
  }
  final firstSeats = rowSeats[0];
  for (int seat = 1; seat <= maxSeat!; seat++) {
    final present = firstSeats.contains(seat);
    for (int r = 1; r < rowSeats.length; r++) {
      if (rowSeats[r].contains(seat) != present) return false;
    }
  }
  return true;
}

