bool fn0(List<List<int>> rectangles, int digit) {
  if (digit < 0 || digit > 9) return false;
  const Map<int, List<List<int>>> patterns = {
    0: [[3,5],[6,7]],
    1: [[2,4],[6,7]],
    2: [[2,3],[5,7]],
    3: [[1,5],[6,7]],
    4: [[1,2],[5,7]],
    5: [[1,3],[6,7]],
    6: [[1,2],[3,7]],
    7: [[1,4],[5,7]],
    8: [[1,3],[4,7]],
    9: [[3,4],[5,7]],
  };
  if (rectangles.isEmpty) return false;
  int? y1, y2;
  for (var r in rectangles) {
    if (r.length != 4) return false;
    int x1 = r[0], yy1 = r[1], x2 = r[2], yy2 = r[3];
    if (x1 < 0 || x2 > 7 || x1 >= x2 || yy1 >= yy2) return false;
    if (y1 == null) {
      y1 = yy1;
      y2 = yy2;
    } else if (yy1 != y1 || yy2 != y2) {
      return false;
    }
  }
  var sorted = List<List<int>>.from(rectangles);
  sorted.sort((a, b) => a[0].compareTo(b[0]));
  for (int i = 1; i < sorted.length; i++) {
    if (sorted[i][0] < sorted[i-1][2]) return false;
  }
  List<List<int>> union = [];
  int curStart = sorted[0][0];
  int curEnd = sorted[0][2];
  for (int i = 1; i < sorted.length; i++) {
    int nx1 = sorted[i][0];
    int nx2 = sorted[i][2];
    if (nx1 <= curEnd) {
      curEnd = nx2 > curEnd ? nx2 : curEnd;
    } else {
      union.add([curStart, curEnd]);
      curStart = nx1;
      curEnd = nx2;
    }
  }
  union.add([curStart, curEnd]);
  var expUnion = patterns[digit]!;
  if (union.length != expUnion.length) return false;
  for (int i = 0; i < union.length; i++) {
    if (union[i][0] != expUnion[i][0] || union[i][1] != expUnion[i][1]) return false;
  }
  return true;
}

