    if (log.isEmpty) continue;
    String decoded = '';
    int i = 0;
    while (i < log.length) {
      String letter = log[i];
      i++;
      String countStr = '';
      while (i < log.length && log[i].codeUnitAt(0) >= 48 && log[i].codeUnitAt(0) <= 57) {
        countStr += log[i];
        i++;
