      int count = int.parse(countStr);
      for (int j = 0; j < count; j++) {
        decoded += letter;
      }
    }
    int checksum = 0;
    for (int k = 0; k < decoded.length; k++) {
      if (decoded[k] == 'C') {
        checksum += 1;
      } else if (decoded[k] == 'D') {
        checksum -= 1;
      }
    }
    if (checksum > 0) {
      result.add(decoded);
    }
  }
  return result;
}

