bool fn0(List<List<int>> grid) {
  Map<int, int> moistureFrequency = <int, int>{};
  int rows = grid.length;
  if (rows == 0) return false;
  int cols = grid[0].length;
  for (int i = 0; i < rows; i++) {
    if (grid[i].length != cols) return false;
    for (int j = 0; j < cols; j++) {
      int moisture = grid[i][j];
      if (moisture < 0) return false;
      moistureFrequency[moisture] = (moistureFrequency[moisture] ?? 0) + 1;
    }
  }
  Map<int, Set<int>> frequencyGroups = <int, Set<int>>{};
  for (var entry in moistureFrequency.entries) {
    int value = entry.key;
    int freq = entry.value;
    if (!frequencyGroups.containsKey(freq)) {
      frequencyGroups[freq] = <int>{};
    }
    frequencyGroups[freq]!.add(value);
  }
  for (var group in frequencyGroups.values) {
    if (group.length != 1) return false;
  }
  return moistureFrequency.isNotEmpty;
}

