import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(String recipe) {
  List<double> amounts = [];
  double scaleFactor = 1.0;
  bool seenScale = false;
  int i = 0;
  while (i < recipe.length) {

    while (i < recipe.length && (recipe[i] == ' ' || recipe[i] == '\t')) {
      i++;
    }
    if (i >= recipe.length) break;
    int c = recipe.codeUnitAt(i);
    if ((c >= 48 && c <= 57) || recipe[i] == '.') {
      String numStr = '';
      while (i < recipe.length && ((recipe.codeUnitAt(i) >= 48 && recipe.codeUnitAt(i) <= 57) || recipe[i] == '.')) {
        numStr += recipe[i];
        i++;
      }
      double val = double.parse(numStr);
      if (!seenScale) {
        amounts.add(val);
      } else {
        scaleFactor = val;
        break;
      }
    } else if ((c >= 65 && c <= 90) || (c >= 97 && c <= 122)) {
      String word = '';
      while (i < recipe.length && ((recipe.codeUnitAt(i) >= 65 && recipe.codeUnitAt(i) <= 90) ||
             (recipe.codeUnitAt(i) >= 97 && recipe.codeUnitAt(i) <= 122))) {
        word += recipe[i];
        i++;
      }
      if (word.toLowerCase() == 'scale') {
        seenScale = true;
      }
    } else {
      i++;
    }
  }
  if (amounts.isEmpty) return <int>[];
  List<int> result = [];
  for (double amt in amounts) {
    result.add((amt * scaleFactor).round());
  }
  return result;
}

