import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<int> ops, int B, int windowSize) {
  if (windowSize > ops.length) return [-1, -1];
  int n = ops.length;
  List<int> freq = List.filled(B, 0);
  List<int> freqCount = List.filled(windowSize + 1, 0);

  for (int i = 0; i < windowSize; i++) {
    int bucket = ops[i];
    int oldF = freq[bucket];
    if (oldF > 0) freqCount[oldF]--;
    freq[bucket] = oldF + 1;
    freqCount[oldF + 1]++;
  }
  int maxFreq = 0;
  for (int f = windowSize; f >= 1; f--) {
    if (freqCount[f] > 0) {
      maxFreq = f;
      break;
    }
  }
  int bestMax = maxFreq;
  int bestStart = 0;
  int bestEnd = windowSize - 1;

  for (int i = windowSize; i < n; i++) {
    int outBucket = ops[i - windowSize];
    int oldOutF = freq[outBucket];
    freqCount[oldOutF]--;
    freq[outBucket] = oldOutF - 1;
    if (oldOutF - 1 > 0) freqCount[oldOutF - 1]++;
    if (oldOutF == maxFreq && freqCount[oldOutF] == 0) {
      while (maxFreq > 0 && freqCount[maxFreq] == 0) maxFreq--;
    }
    int inBucket = ops[i];
    int oldInF = freq[inBucket];
    if (oldInF > 0) freqCount[oldInF]--;
    freq[inBucket] = oldInF + 1;
    freqCount[oldInF + 1]++;
    if (oldInF + 1 > maxFreq) maxFreq = oldInF + 1;
    if (maxFreq < bestMax) {
      bestMax = maxFreq;
      bestStart = i - windowSize + 1;
      bestEnd = i;
    }
  }
  return [bestStart, bestEnd];
}

