import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<List<int>> pixels) {

  for (final p in pixels) {
    if (p.length != 3) return false;
    for (final c in p) {
      if (c < 0 || c > 255) return false;
    }
  }

  int luminance(List<int> p) => 299 * p[0] + 587 * p[1] + 114 * p[2];

  int chroma(List<int> p) {
    var hi = p[0];
    var lo = p[0];
    for (var i = 1; i < 3; i++) {
      if (p[i] > hi) hi = p[i];
      if (p[i] < lo) lo = p[i];
    }
    return hi - lo;
  }

  int compare(List<int> a, List<int> b) {
    final la = luminance(a);
    final lb = luminance(b);
    if (la != lb) return la < lb ? -1 : 1;
    final ca = chroma(a);
    final cb = chroma(b);
    if (ca != cb) return ca > cb ? -1 : 1;
    for (var i = 0; i < 3; i++) {
      if (a[i] != b[i]) return a[i] < b[i] ? -1 : 1;
    }
    return 0;
  }
  for (var i = 0; i + 1 < pixels.length; i++) {
    if (compare(pixels[i], pixels[i + 1]) > 0) return false;
  }
  return true;
}

