Set<int> fn0(List<int> entries, int priorityMask) {
  final result = <int>{};
  for (final entry in entries) {
    final isArchived = (entry >> 28) & 1;
    if (isArchived == 1) continue;
    final categoryCode = (entry >> 13) & 0x7F;
    final priority = (entry >> 20) & 0xFF;
    final masked = priority & priorityMask;
    int count = 0;
    int temp = masked;
    while (temp > 0) {
      count += temp & 1;
      temp >>= 1;
    }
    if (count % 2 == 1) {
      result.add(categoryCode);
    }
  }
  return result;
}

