String fn0(Map<String, List<int>> precinctVotes) {
  if (precinctVotes.isEmpty) return "NO CANDIDATES";

  Map<String, int> totals = {};
  for (var entry in precinctVotes.entries) {
    int sum = 0;
    for (var v in entry.value) {
      sum += v;
    }
    totals[entry.key] = sum;
  }

  int grandTotal = 0;
  for (var v in totals.values) {
    grandTotal += v;
  }
  if (grandTotal == 0) return "NO VOTES";

  List<String> candidates = totals.keys.toList();
  candidates.sort((a, b) {
    int cmp = totals[b]! - totals[a]!;
    if (cmp != 0) return cmp;
    return a.compareTo(b);
  });

  int topVotes = totals[candidates[0]]!;
  if (topVotes * 2 > grandTotal) {
    return "ELECTED: ${candidates[0]}";
  }
  return "RUNOFF: ${candidates[0]} vs ${candidates[1]}";
}

