import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<String> operations) {
  final Set<int> activeMinutes = <int>{};
  final List<String> history = <String>[];

  Set<int> shift(Set<int> source, int delta) {
    final Set<int> shifted = <int>{};
    for (final int minute in source) {
      int next = (minute + delta) % 1440;
      if (next < 0) {
        next += 1440;
      }
      shifted.add(next);
    }
    return shifted;
  }

  for (final String operation in operations) {
    final List<String> parts = operation.split(' ');
    final String type = parts[0];

    if (type == 'ADD') {
      final int minute = int.parse(parts[1]);
      if (minute >= 0 && minute < 1440 && activeMinutes.add(minute)) {
        history.add('REMOVE $minute');
      } else {
        history.add('NOP');
      }
    } else if (type == 'REMOVE') {
      final int minute = int.parse(parts[1]);
      if (activeMinutes.remove(minute)) {
        history.add('ADD $minute');
      } else {
        history.add('NOP');
      }
    } else if (type == 'SHIFT') {
      final int delta = int.parse(parts[1]);
      final Set<int> shifted = shift(activeMinutes, delta);
      activeMinutes
        ..clear()
        ..addAll(shifted);
      history.add('SHIFT ${-delta}');
    } else if (type == 'UNDO') {
      int count = int.parse(parts[1]);
      while (count > 0 && history.isNotEmpty) {
        final String inverse = history.removeLast();
        if (inverse == 'NOP') {
          count--;
          continue;
        }

        final List<String> undoParts = inverse.split(' ');
        if (undoParts[0] == 'ADD') {
          activeMinutes.add(int.parse(undoParts[1]));
        } else if (undoParts[0] == 'REMOVE') {
          activeMinutes.remove(int.parse(undoParts[1]));
        } else if (undoParts[0] == 'SHIFT') {
          final int delta = int.parse(undoParts[1]);
          final Set<int> shifted = shift(activeMinutes, delta);
          activeMinutes
            ..clear()
            ..addAll(shifted);
        }
        count--;
      }
    }
  }

  return activeMinutes;
}

