import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(String data) {
  if (data.isEmpty) return 0;

  int count = 0;
  int i = 0;
  final int n = data.length;
  bool insideComment = false;
  String currentToken = '';
  List<String> rgbParts = [];

  void finalizeToken() {
    if (insideComment) return;
    if (currentToken.isNotEmpty) {
      final trimmed = currentToken.trim();
      if (trimmed.isNotEmpty) {
        rgbParts.add(trimmed);
      }
      currentToken = '';
    }
    if (rgbParts.length == 3) {

      bool valid = true;
      for (final part in rgbParts) {
        final maybeVal = int.tryParse(part);
        if (maybeVal == null || maybeVal < 0 || maybeVal > 255) {
          valid = false;
          break;
        }
      }
      if (valid) count++;
      rgbParts = [];
    }
  }

  while (i < n) {
    if (!insideComment && i + 1 < n && data[i] == '/' && data[i + 1] == '*') {
      finalizeToken();
      insideComment = true;
      i += 2;
      continue;
    }
    if (insideComment && i + 1 < n && data[i] == '*' && data[i + 1] == '/') {
      insideComment = false;
      i += 2;
      continue;
    }

    if (!insideComment) {
      if (data[i] == ',' || data[i] == ';' || data[i] == ' ' || data[i] == '\t' || data[i] == '\n') {
        finalizeToken();
        if (data[i] == ';') {

          rgbParts = [];
        }
        i++;
        continue;
      }
      currentToken += data[i];
    }
    i++;
  }
  finalizeToken();
  return count;
}

