double fn0(List<int> sortedUnits, int targetUnits) {
  if (sortedUnits.isEmpty) {
    return -1.0;
  }

  int left = 0;
  int right = sortedUnits.length;

  while (left < right) {
    int mid = left + ((right - left) ~/ 2);

    if (sortedUnits[mid] < targetUnits) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }

  int firstPosition = left;

  if (firstPosition >= sortedUnits.length ||
      sortedUnits[firstPosition] != targetUnits) {
    return firstPosition - 0.5;
  }

  right = sortedUnits.length;

  while (left < right) {
    int mid = left + ((right - left) ~/ 2);

    if (sortedUnits[mid] <= targetUnits) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }

  int lastPosition = left - 1;
  return (firstPosition + lastPosition) / 2.0;
}

