@pragma('vm:entry-point')
bool fn0(String bits) {
  if (bits.length != 95) return false;
  for (int i = 0; i < bits.length; i++) {
    if (bits[i] != '0' && bits[i] != '1') return false;
  }
  const Map<String, int> leftPatterns = {
    '0001101': 0,
    '0011001': 1,
    '0010011': 2,
    '0111101': 3,
    '0100011': 4,
    '0110001': 5,
    '0101111': 6,
    '0111011': 7,
    '0110111': 8,
    '0001011': 9,
  };
  int i = 0;
  if (bits.substring(i, i + 3) != '101') return false;
  i += 3;
  List<int> digits = [];
  for (int j = 0; j < 6; j++) {
    String chunk = bits.substring(i, i + 7);
    int? digit = leftPatterns[chunk];
    if (digit == null) return false;
    digits.add(digit);
    i += 7;
  }
  if (bits.substring(i, i + 5) != '01010') return false;
  i += 5;
  for (int j = 0; j < 6; j++) {
    String chunk = bits.substring(i, i + 7);
    String inverted = chunk.split('').map((c) => c == '0' ? '1' : '0').join();
    int? digit = leftPatterns[inverted];
    if (digit == null) return false;
    digits.add(digit);
    i += 7;
  }
  if (bits.substring(i, i + 3) != '101') return false;
  i += 3;
  if (i != bits.length) return false;
  int sumOdd = 0, sumEven = 0;
  for (int k = 0; k < 11; k++) {
    if ((k + 1) % 2 == 1) {
      sumOdd += digits[k];
    } else {
      sumEven += digits[k];
    }
  }
  int total = sumOdd * 3 + sumEven;
  int check = (10 - (total % 10)) % 10;
  return digits[11] == check;
}

