import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<String> maze, String commands) {
  int startR = -1, startC = -1;
  for (int r = 0; r < maze.length; r++) {
    int idx = maze[r].indexOf('S');
    if (idx != -1) { startR = r; startC = idx; break; }
  }
  if (startR == -1) return false;

  List<int> pos = [startR, startC];
  List<bool> valid = [true];

  int parse(String s, int i, int end) {
    while (i < end && valid[0]) {
      int code = s.codeUnitAt(i);
      if (code == 41) return i + 1; 
      if (code >= 48 && code <= 57) { 
        int num = 0;
        while (i < end && s.codeUnitAt(i) >= 48 && s.codeUnitAt(i) <= 57) {
          num = num * 10 + (s.codeUnitAt(i) - 48);
          i++;
        }
        if (i >= end || s.codeUnitAt(i) != 40) { valid[0] = false; break; } 
        i++;
        int groupStart = i;
        int paren = 1;
        while (i < end && paren > 0) {
          if (s.codeUnitAt(i) == 40) paren++;
          else if (s.codeUnitAt(i) == 41) paren--;
          i++;
        }
        if (paren != 0) { valid[0] = false; break; }
        int groupEnd = i - 1;
        for (int rep = 0; rep < num; rep++) {
          parse(s, groupStart, groupEnd);
          if (!valid[0]) break;
        }
      } else {
        int dr = 0, dc = 0;
        if (code == 85) dr = -1; 
        else if (code == 68) dr = 1; 
        else if (code == 76) dc = -1; 
        else if (code == 82) dc = 1; 
        else { valid[0] = false; break; }
        int nr = pos[0] + dr, nc = pos[1] + dc;
        if (nr < 0 || nr >= maze.length || nc < 0 || nc >= maze[0].length || maze[nr][nc] == '#') {
          valid[0] = false; break;
        }
        pos[0] = nr; pos[1] = nc;
        i++;
      }
    }
    return i;
  }

  parse(commands, 0, commands.length);
  if (!valid[0]) return false;
  return maze[pos[0]][pos[1]] == 'E';
}

