int fn0(List<List<int>> zones) {
  if (zones.isEmpty) return 0;
  final ySet = <int>{};
  final events = <List<int>>[];
  for (final z in zones) {
    final x1 = z[0], y1 = z[1], x2 = z[2], y2 = z[3], d = z[4];
    ySet.add(y1);
    ySet.add(y2 + 1);
    events.add([x1, 1, y1, y2 + 1, d]);
    events.add([x2 + 1, -1, y1, y2 + 1, d]);
  }
  final yCoords = ySet.toList()..sort();
  final yIndex = <int, int>{};
  for (var i = 0; i < yCoords.length; i++) {
    yIndex[yCoords[i]] = i;
  }
  events.sort((a, b) => a[0].compareTo(b[0]));
  final diff = List.filled(yCoords.length, 0);
  int maxOverlap = 0;
  int i = 0;
  while (i < events.length) {
    final currentX = events[i][0];
    while (i < events.length && events[i][0] == currentX) {
      final e = events[i];
      final yStart = yIndex[e[2]]!;
      final yEnd = yIndex[e[3]]!;
      final delta = e[1] * e[4];
      diff[yStart] += delta;
      diff[yEnd] -= delta;
      i++;
    }
    int currentSum = 0;
    for (final val in diff) {
      currentSum += val;
      if (currentSum > maxOverlap) {
        maxOverlap = currentSum;
      }
    }
  }
  return maxOverlap;
}

