Set<int> fn0(List<String> logLines, int count) {
  var records = <MapEntry<int, int>>[];
  for (var line in logLines) {
    var parts = line.split(' ');
    if (parts.length < 2) continue;
    var status = int.tryParse(parts[parts.length - 2]) ?? 0;
    var size = int.tryParse(parts.last) ?? 0;
    records.add(MapEntry(status, size));
  }
  records.sort((a, b) {
    int cmp = b.value.compareTo(a.value);
    if (cmp != 0) return cmp;
    return a.key.compareTo(b.key);
  });
  var result = <int>{};
  for (var rec in records) {
    if (result.length >= count) break;
    result.add(rec.key);
  }
  return result;
}

