@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<List<int>> board) {
  if (board.isEmpty || board[0].isEmpty) return [0, 0, 0];
  int rows = board.length;
  int cols = board[0].length;
  List<int> spiral = [];
  int top = 0, bottom = rows - 1, left = 0, right = cols - 1;
  while (top <= bottom && left <= right) {
    for (int i = left; i <= right; i++) {
      spiral.add(board[top][i]);
    }
    top++;
    for (int i = top; i <= bottom; i++) {
      spiral.add(board[i][right]);
    }
    right--;
    if (top <= bottom) {
      for (int i = right; i >= left; i--) {
        spiral.add(board[bottom][i]);
      }
      bottom--;
    }
    if (left <= right) {
      for (int i = bottom; i >= top; i--) {
        spiral.add(board[i][left]);
      }
      left++;
    }
  }
  int totalSum = 0;
  int matchCount = 0;
  int maxStreak = 0;
  int currentStreak = 0;
  for (int i = 0; i < spiral.length; i++) {
    totalSum += spiral[i];
    if (i > 0 && spiral[i] + spiral[i - 1] == 7) {
      matchCount++;
      currentStreak++;
      if (currentStreak > maxStreak) maxStreak = currentStreak;
    } else {
      currentStreak = 0;
    }
  }
  return [totalSum, matchCount, maxStreak];
}

