String fn0(List<String> commands) {
  List<String> playlist = [];
  List<String> undoStack = [];
  for (String cmd in commands) {
    if (cmd.startsWith('ADD:')) {
      String song = cmd.substring(4);
      playlist.add(song);
      undoStack.add('ADD:$song');
    } else if (cmd == 'DROP') {
      if (playlist.isNotEmpty) {
        String song = playlist.removeLast();
        undoStack.add('DROP:$song');
      }
    } else if (cmd == 'UNDO') {
      if (undoStack.isNotEmpty) {
        String action = undoStack.removeLast();
        if (action.startsWith('ADD:')) {
          if (playlist.isNotEmpty) playlist.removeLast();
        } else if (action.startsWith('DROP:')) {
          String song = action.substring(5);
          playlist.add(song);
        }
      }
    }
  }
  return playlist.isEmpty ? 'Empty' : playlist.join(' | ');
}

