import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<int> thermostatIds, List<int> startMinutes, List<int> endMinutes, List<int> setpointHalves) {
  int n = thermostatIds.length;
  if (startMinutes.length < n) n = startMinutes.length;
  if (endMinutes.length < n) n = endMinutes.length;
  if (setpointHalves.length < n) n = setpointHalves.length;

  final Map<int, List<int?>> schedules = <int, List<int?>>{};
  for (int i = 0; i < n; i++) {
    int s = startMinutes[i];
    int e = endMinutes[i];
    if (s < 0) s = 0;
    if (s > 1440) s = 1440;
    if (e < 0) e = 0;
    if (e > 1440) e = 1440;
    if (s == e) continue;

    final int id = thermostatIds[i];
    final int temp = setpointHalves[i];
    List<int?>? day = schedules[id];
    if (day == null) {
      day = List<int?>.filled(1440, null);
      schedules[id] = day;
    }

    void writeRange(int a, int b) {
      for (int m = a; m < b; m++) {
        day![m] = temp;
      }
    }

    if (s < e) {
      writeRange(s, e);
    } else {
      writeRange(s, 1440);
      writeRange(0, e);
    }
  }

  final Set<int> result = <int>{};
  for (final MapEntry<int, List<int?>> room in schedules.entries) {
    final Map<int, int> counts = <int, int>{};
    final Map<int, int> runs = <int, int>{};
    final List<int?> day = room.value;

    for (int m = 0; m < 1440; m++) {
      final int? temp = day[m];
      if (temp != null) counts[temp] = (counts[temp] ?? 0) + 1;
    }
    if (counts.isEmpty) continue;

    for (int m = 0; m < 1440; m++) {
      final int? temp = day[m];
      if (temp == null) continue;
      final int? previous = day[(m + 1439) % 1440];
      if (previous != temp) runs[temp] = (runs[temp] ?? 0) + 1;
    }
    for (final int temp in counts.keys) {
      if (!runs.containsKey(temp)) runs[temp] = 1;
    }

    int maxCount = 0;
    for (final int count in counts.values) {
      if (count > maxCount) maxCount = count;
    }
    for (final MapEntry<int, int> entry in counts.entries) {
      if (entry.value == maxCount && (runs[entry.key] ?? 0) > 1) {
        result.add(room.key);
        break;
      }
    }
  }
  return result;
}

