import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<int> ledger, int maxLock) {
  if (ledger.length % 3 != 0) return false;
  if (ledger.isEmpty) return true;

  final events = <int, int>{};
  int totalHighRiskDuration = 0;
  int totalLowRiskDuration = 0;
  int totalAmount = 0;
  int weightedSum = 0;

  for (int i = 0; i < ledger.length; i += 3) {
    final day = ledger[i];
    final amount = ledger[i + 1];
    final duration = ledger[i + 2];

    if (day <= 0 || amount <= 0 || duration <= 0) return false;

    final settlementDay = day + duration;
    final dayOfWeek = settlementDay % 7;

    if (dayOfWeek == 0 || dayOfWeek == 6) return false;

    if (amount > 1000) {
      if (dayOfWeek == 5) return false;
      totalHighRiskDuration += duration;
    } else {
      totalLowRiskDuration += duration;
    }

    totalAmount += amount;
    weightedSum += amount * settlementDay;

    events[day] = (events[day] ?? 0) + amount;
    events[settlementDay] = (events[settlementDay] ?? 0) - amount;
  }

  if (totalHighRiskDuration > totalLowRiskDuration) return false;
  if (weightedSum % totalAmount != 0) return false;

  final sortedDays = events.keys.toList()..sort();
  int currentLock = 0;

  for (final d in sortedDays) {
    currentLock += events[d]!;
    if (currentLock > maxLock) return false;
  }

  return currentLock == 0;
}

