double fn0(String inventoryCode) {
  if (inventoryCode.isEmpty) {
    return 0.0;
  }
  int totalChars = 0;
  int runs = 0;
  String? lastChar;

  for (int i = 0; i < inventoryCode.length; i++) {
    String currentChar = inventoryCode[i];
    int code = currentChar.codeUnitAt(0);
    bool isAlphaNum = (code >= 48 && code <= 57) ||
                      (code >= 65 && code <= 90) ||
                      (code >= 97 && code <= 122);

    if (isAlphaNum) {
      totalChars++;
      if (lastChar == null || currentChar != lastChar) {
        runs++;
      }
      lastChar = currentChar;
    } else {
      lastChar = null;
    }
  }

  if (totalChars == 0) {
    return 0.0;
  }

  return (totalChars - runs) / totalChars;
}

