int fn0(Map<String, int> rowCapacities, List<String> requests) {
  Map<String, List<int>> rowGroups = {};
  Map<String, int> rowFrequency = {};

  for (String req in requests) {
    int dashIdx = req.indexOf('-');
    int groupSize = int.parse(req.substring(0, dashIdx));
    String row = req.substring(dashIdx + 1);

    rowGroups.putIfAbsent(row, () => []);
    rowGroups[row]!.add(groupSize);

    rowFrequency[row] = (rowFrequency[row] ?? 0) + 1;
  }

  List<String> sortedRows = rowFrequency.keys.toList();
  sortedRows.sort((a, b) {
    int freqCompare = rowFrequency[b]!.compareTo(rowFrequency[a]!);
    if (freqCompare != 0) return freqCompare;
    return a.compareTo(b);
  });

  int totalGroups = 0;

  for (String row in sortedRows) {
    int capacity = rowCapacities[row] ?? 0;
    List<int> groups = rowGroups[row] ?? [];
    groups.sort();

    for (int size in groups) {
      if (size <= capacity) {
        capacity -= size;
        totalGroups++;
      }
    }
  }

  return totalGroups;
}

