int _parseTrace(String trace, int index, int depth, List<int> depths) {
  while (index < trace.length) {
    if (trace[index] == '(') {
      index = _parseTrace(trace, index + 1, depth + 1, depths);
    } else if (trace[index] == ')') {
      return index + 1;
    } else if (trace[index] == 'E') {
      depths.add(depth);
      index++;
    } else {
      index++;
    }
  }
  return index;
}

