import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<int> packetSizes, int maxGap) {
  if (packetSizes.isEmpty) {
    return 0.0;
  }

  Map<int, int> frequencies = {};
  for (int size in packetSizes) {
    frequencies[size] = (frequencies[size] ?? 0) + 1;
  }

  List<int> uniqueSizes = frequencies.keys.toList()..sort();
  List<int> clusterTotals = [];
  int points = 0;
  int index = 0;

  while (index < uniqueSizes.length) {
    List<int> cluster = [uniqueSizes[index]];
    int next = index + 1;

    while (next < uniqueSizes.length &&
        uniqueSizes[next] - uniqueSizes[next - 1] <= maxGap) {
      cluster.add(uniqueSizes[next]);
      next++;
    }

    int dominantFrequency = 0;
    int singletonKinds = 0;
    int evenFrequencyKinds = 0;
    int clusterPacketTotal = 0;

    for (int size in cluster) {
      int frequency = frequencies[size]!;
      clusterPacketTotal += frequency;

      if (frequency > dominantFrequency) {
        dominantFrequency = frequency;
      }

      if (frequency == 1) {
        singletonKinds++;
      }

      if (frequency % 2 == 0) {
        evenFrequencyKinds++;
      }
    }

    points += dominantFrequency * 3;
    points -= singletonKinds;
    points += evenFrequencyKinds * 2;

    if (cluster.length >= 3 && clusterPacketTotal.isOdd) {
      points += 1;
    }

    clusterTotals.add(clusterPacketTotal);
    index = next;
  }

  if (clusterTotals.length > 1) {
    int minTotal = clusterTotals.first;
    int maxTotal = clusterTotals.first;

    for (int total in clusterTotals) {
      if (total < minTotal) {
        minTotal = total;
      }
      if (total > maxTotal) {
        maxTotal = total;
      }
    }

    if (minTotal == maxTotal) {
      points += 2;
    }
  }

  return points / 4.0;
}

