List<String> fn0(List<int> pricesCents, int budgetCents) {

  int roundToNickel(int cents) {
    final r = cents % 5;
    return r < 3 ? cents - r : cents + (5 - r);
  }

  String fmt(int cents) {
    final dollars = cents ~/ 100;
    final rem = cents % 100;
    return '\$$dollars.${rem.toString().padLeft(2, '0')}';
  }

  final n = pricesCents.length;
  final result = <String>[];
  var right = 0;
  var sum = 0;
  for (var left = 0; left < n; left++) {
    while (right < n &&
        roundToNickel(sum + pricesCents[right]) <= budgetCents) {
      sum += pricesCents[right];
      right++;
    }
    if (right == left) {
      result.add('$left:none');
      right = left + 1;
    } else {
      result.add('$left..${right - 1}=${fmt(roundToNickel(sum))}');
      sum -= pricesCents[left];
    }
  }
  return result;
}

