import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(String input) {
  if (input.isEmpty) return "[]";

  const IDLE = 0, READ_NUM = 1, AFTER_COLON = 2, READ_COUNT = 3;
  const AFTER_DOTDOT = 4, READ_RANGE_END = 5;

  Map<int, int> buckets = {};
  int state = IDLE;
  int num = 0, bucketIdx = 0, count = 0;

  String s = input + ',';

  for (int i = 0; i < s.length; i++) {
    int code = s.codeUnitAt(i);
    bool digit = code >= 48 && code <= 57;
    String c = s[i];

    switch (state) {
      case IDLE:
        if (digit) {
          num = code - 48;
          state = READ_NUM;
        }
        break;
      case READ_NUM:
        if (digit) {
          num = num * 10 + (code - 48);
        } else if (c == ':') {
          bucketIdx = num;
          state = AFTER_COLON;
        } else if (c == ',') {
          buckets[num] = (buckets[num] ?? 0) + 1;
          state = IDLE;
        }
        break;
      case AFTER_COLON:
        if (digit) {
          num = code - 48;
          state = READ_COUNT;
        }
        break;
      case READ_COUNT:
        if (digit) {
          num = num * 10 + (code - 48);
        } else if (c == '.' && i + 1 < s.length && s[i + 1] == '.') {
          count = num;
          state = AFTER_DOTDOT;
          i++;
        } else if (c == ',') {
          buckets[bucketIdx] = (buckets[bucketIdx] ?? 0) + num;
          state = IDLE;
        }
        break;
      case AFTER_DOTDOT:
        if (digit) {
          num = code - 48;
          state = READ_RANGE_END;
        }
        break;
      case READ_RANGE_END:
        if (digit) {
          num = num * 10 + (code - 48);
        } else if (c == ',') {
          for (int b = bucketIdx; b <= num; b++) {
            buckets[b] = (buckets[b] ?? 0) + count;
          }
          state = IDLE;
        }
        break;
    }
  }

  if (buckets.isEmpty) return "[]";
  List<int> keys = buckets.keys.toList()..sort();
  List<String> parts = [];
  for (int k in keys) {
    parts.add('$k:${buckets[k]}');
  }
  return '[${parts.join(',')}]';
}

