import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(String pixels) {
  List<String> tokens = pixels.split('|');
  String previous = '';
  int switches = 0;

  for (String token in tokens) {
    token = token.trim();
    if (token.isEmpty) {
      continue;
    }

    List<String> parts = token.split(',');
    if (parts.length != 3) {
      continue;
    }

    int? r = int.tryParse(parts[0].trim());
    int? g = int.tryParse(parts[1].trim());
    int? b = int.tryParse(parts[2].trim());

    if (r == null || g == null || b == null) {
      continue;
    }

    if (r < 0 || r > 255 || g < 0 || g > 255 || b < 0 || b > 255) {
      continue;
    }

    if (r + g + b < 384) {
      continue;
    }

    String dominant = '';
    if (r > g && r > b) {
      dominant = 'R';
    } else if (g > r && g > b) {
      dominant = 'G';
    } else if (b > r && b > g) {
      dominant = 'B';
    } else {
      continue;
    }

    if (previous.isNotEmpty && previous != dominant) {
      switches++;
    }

    previous = dominant;
  }

  return switches;
}

