List<String> fn0(List<List<String>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return [];
  List<String> spiral = [];
  int top = 0, bottom = grid.length - 1;
  int left = 0, right = grid[0].length - 1;
  while (top <= bottom && left <= right) {
    for (int i = left; i <= right; i++) spiral.add(grid[top][i]);
    top++;
    for (int i = top; i <= bottom; i++) spiral.add(grid[i][right]);
    right--;
    if (top <= bottom) {
