    }
    if (left <= right) {
      for (int i = bottom; i >= top; i--) spiral.add(grid[i][left]);
      left++;
    }
  }
  String sequence = spiral.join('');
  List<String> wordStrings = sequence.split('*');
  Map<String, String> morse = {
    '.-': 'A', '-...': 'B', '-.-.': 'C', '-..': 'D', '.': 'E',
    '..-.': 'F', '--.': 'G', '....': 'H', '..': 'I', '.---': 'J',
