  if (draws < 0 || draws > deck.length) {
    return <int>{};
  }

  Set<int> totals = <int>{};

  void search(int left, int right, int remaining, int total) {
    if (remaining == 0) {
      totals.add(total);
      return;
    }

    if (left > right) {
      return;
    }

    search(left + 1, right, remaining - 1, total + deck[left]);

    if (left != right) {
      search(left, right - 1, remaining - 1, total + deck[right]);
    }
  }

  search(0, deck.length - 1, draws, 0);
  return totals;
}

