bool fn0(List<String> tokens, String targetColor) {
  List<int> stack = [];
  for (String token in tokens) {
    if (token == 'avg' || token == 'max' || token == 'min') {
      if (stack.length < 2) return false;
      int b = stack.removeLast();
      int a = stack.removeLast();
      int ar = (a >> 16) & 0xFF, ag = (a >> 8) & 0xFF, ab = a & 0xFF;
      int br = (b >> 16) & 0xFF, bg = (b >> 8) & 0xFF, bb = b & 0xFF;
      int rr, rg, rb;
      if (token == 'avg') {
        rr = (ar + br) ~/ 2;
        rg = (ag + bg) ~/ 2;
        rb = (ab + bb) ~/ 2;
      } else if (token == 'max') {
        rr = ar > br ? ar : br;
        rg = ag > bg ? ag : bg;
        rb = ab > bb ? ab : bb;
      } else {
        rr = ar < br ? ar : br;
        rg = ag < bg ? ag : bg;
        rb = ab < bb ? ab : bb;
      }
      stack.add((rr << 16) | (rg << 8) | rb);
    } else if (token == 'inv') {
      if (stack.isEmpty) return false;
      int c = stack.removeLast();
      int r = 255 - ((c >> 16) & 0xFF);
      int g = 255 - ((c >> 8) & 0xFF);
      int b = 255 - (c & 0xFF);
      stack.add((r << 16) | (g << 8) | b);
    } else if (token.length == 6) {
      int? val = int.tryParse(token, radix: 16);
      if (val == null || val < 0 || val > 0xFFFFFF) return false;
      stack.add(val);
    } else {
      return false;
    }
  }
  int? target = int.tryParse(targetColor, radix: 16);
  if (target == null) return false;
  return stack.length == 1 && stack[0] == target;
}

