@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<int> archivedLineIds, int startLineId, int k) {
  if (k <= 0) {
    return startLineId;
  }

  int left = 0;
  int right = archivedLineIds.length;

  while (left < right) {
    int mid = left + ((right - left) >> 1);
    if (archivedLineIds[mid] < startLineId) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }

  int firstRelevant = left;

  if (firstRelevant >= archivedLineIds.length) {
    return startLineId + k - 1;
  }

  int missingBeforeFirst =
      archivedLineIds[firstRelevant] - startLineId;

  if (k <= missingBeforeFirst) {
    return startLineId + k - 1;
  }

  left = firstRelevant;
  right = archivedLineIds.length - 1;

  while (left < right) {
    int mid = left + ((right - left) >> 1);
    int missingUntilMid =
        archivedLineIds[mid] - startLineId - (mid - firstRelevant);

    if (missingUntilMid >= k) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }

  int index = left;
  int missingBeforeIndex = archivedLineIds[index] -
      startLineId -
      (index - firstRelevant);

  int previousLine = archivedLineIds[index - 1];
  int missingBeforePrevious = archivedLineIds[index - 1] -
      startLineId -
      ((index - 1) - firstRelevant);

  return previousLine + (k - missingBeforePrevious);
}

