import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<String> rows, int maxDensityGap) {
  List<int> densities = [];
  List<int> spans = [];

  for (String row in rows) {
    int density = 0;
    int first = -1;
    int last = -1;

    for (int i = 0; i < row.length; i++) {
      if (row[i] != ' ') {
        density++;
        if (first == -1) {
          first = i;
        }
        last = i;
      }
    }

    densities.add(density);
    spans.add(first == -1 ? 0 : last - first + 1);
  }

  List<int> order = List<int>.generate(rows.length, (i) => i);
  order.sort((a, b) {
    int byDensity = densities[b] - densities[a];
    if (byDensity != 0) {
      return byDensity;
    }

    int bySpan = spans[a] - spans[b];
    if (bySpan != 0) {
      return bySpan;
    }

    int byText = rows[a].trim().compareTo(rows[b].trim());
    if (byText != 0) {
      return byText;
    }

    return a - b;
  });

  Set<int> result = <int>{};

  for (int i = 0; i < order.length - 1; i++) {
    int left = order[i];
    int right = order[i + 1];

    if ((densities[left] - densities[right]).abs() <= maxDensityGap &&
        (spans[left] - spans[right]).abs() <= 1) {
      result.add(left);
      result.add(right);
    }
  }

  return result;
}

