import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(String log) {
  int alerts = 0;
  int? previous;
  String mode = '?';
  int i = 0;

  while (i < log.length) {
    String type = log[i];

    if ((type != 'R' && type != 'F') || i + 1 >= log.length) {
      alerts += 2;
      while (i < log.length && log[i] != ',') {
        i++;
      }
      if (i < log.length) {
        i++;
      }
      previous = null;
      mode = '?';
      continue;
    }

    i++;
    int value = 0;
    bool hasDigit = false;

    while (i < log.length && log[i] != ',') {
      int code = log.codeUnitAt(i);

      if (code < 48 || code > 57) {
        alerts += 2;
        hasDigit = false;
        while (i < log.length && log[i] != ',') {
          i++;
        }
        break;
      }

      value = value * 10 + (code - 48);
      hasDigit = true;
      i++;
    }

    if (hasDigit) {
      if (previous != null) {
        if (type == 'R') {
          if (value <= previous!) {
            alerts++;
          }
          if (mode == 'F' && value > previous!) {
            alerts++;
          }
        } else {
          if (value >= previous!) {
            alerts++;
          }
          if (mode == 'R' && value < previous!) {
            alerts++;
          }
        }
      }

      previous = value;
      mode = type;
    } else {
      previous = null;
      mode = '?';
    }

    if (i < log.length && log[i] == ',') {
      i++;
    }
  }

  return alerts;
}

