double fn0(List<String> destinations, List<int> weights) {
  if (destinations.isEmpty) return 0.0;
  final freq = <String, int>{};
  final sum = <String, int>{};
  for (int i = 0; i < destinations.length; i++) {
    final dest = destinations[i];
    final w = weights[i];
    freq[dest] = (freq[dest] ?? 0) + 1;
    sum[dest] = (sum[dest] ?? 0) + w;
  }
  int maxFreq = 0;
  for (final f in freq.values) {
    if (f > maxFreq) maxFreq = f;
  }
  final candidates = <String>[];
  for (final entry in freq.entries) {
    if (entry.value == maxFreq) candidates.add(entry.key);
  }
  String best = candidates[0];
  int bestWeight = sum[best]!;
  for (final c in candidates) {
    final w = sum[c]!;
    if (w > bestWeight) {
      best = c;
      bestWeight = w;
    }
  }
  return bestWeight / freq[best]!;
}

