Map<String, int> fn0(String sequence) {
  List<String> stack = [];
  for (int i = 0; i < sequence.length; i++) {
    String ch = sequence[i];
    if (ch == 'A' || ch == 'T' || ch == 'G' || ch == 'C') {
      stack.add(ch);
    } else if (ch == 'x') {
      if (stack.isNotEmpty) stack.removeLast();
    } else if (ch == 'd') {
      if (stack.isNotEmpty) stack.add(stack.last);
    } else if (ch == 'r') {
      if (stack.length >= 2) {
        String top = stack.removeLast();
        String second = stack.removeLast();
        stack.add(top);
        stack.add(second);
      }
    }
  }
  Map<String, int> result = {};
  for (String base in stack) {
    result[base] = (result[base] ?? 0) + 1;
  }
  return result;
}

