@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(List<int> departures) {
  if (departures.isEmpty) return "No departures";

  Map<int, List<int>> hourGroups = {};
  for (int time in departures) {
    int hour = time ~/ 60;
    hourGroups.putIfAbsent(hour, () => []);
    hourGroups[hour]!.add(time % 60);
  }

  int maxCount = hourGroups.values.map((v) => v.length).reduce((a, b) => a > b ? a : b);
  Set<int> busiestHours = hourGroups.entries
      .where((e) => e.value.length == maxCount)
      .map((e) => e.key)
      .toSet();

  int earliestHour = busiestHours.reduce((a, b) => a < b ? a : b);

  Map<int, int> minuteFreq = {};
  for (int hour in busiestHours) {
    for (int minute in hourGroups[hour]!) {
      minuteFreq[minute] = (minuteFreq[minute] ?? 0) + 1;
    }
  }

  int maxMinuteFreq = minuteFreq.values.reduce((a, b) => a > b ? a : b);
  int mostCommonMinute = minuteFreq.entries
      .where((e) => e.value == maxMinuteFreq)
      .map((e) => e.key)
      .reduce((a, b) => a < b ? a : b);

  int distinctCount = minuteFreq.length;
  String hh = earliestHour.toString().padLeft(2, '0');
  String mm = mostCommonMinute.toString().padLeft(2, '0');
  return "Busiest: $hh:$mm, $maxCount trains, $distinctCount distinct minutes";
}

