@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<int> ratings, int maxSkip) {




  final int n = ratings.length;
  if (n == 0) return 0;
  const int negInf = -1000000000;
  final List<int> dp = List<int>.filled(n, negInf);
  for (int i = 0; i < n; i++) {
    int best = negInf;

    if (i <= maxSkip) best = 0;

    int lo = i - maxSkip - 1;
    if (lo < 0) lo = 0;
    for (int j = lo; j < i; j++) {
      if (dp[j] > best) best = dp[j];
    }
    if (best > negInf) dp[i] = ratings[i] + best;
  }
  int answer = negInf;

  if (n <= maxSkip) answer = 0;

  int lo = n - 1 - maxSkip;
  if (lo < 0) lo = 0;
  for (int i = lo; i < n; i++) {
    if (dp[i] > answer) answer = dp[i];
  }
  return answer;
}

