import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(String text, Map<String, String> corrections) {
  int editDistance(String a, String b) {
    int m = a.length, n = b.length;
    List<List<int>> dp = List.generate(m + 1, (i) => List.filled(n + 1, 0));
    for (int i = 0; i <= m; i++) dp[i][0] = i;
    for (int j = 0; j <= n; j++) dp[0][j] = j;
    for (int i = 1; i <= m; i++) {
      for (int j = 1; j <= n; j++) {
        int cost = a[i - 1] == b[j - 1] ? 0 : 1;
        dp[i][j] = [dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + cost].reduce((x, y) => x < y ? x : y);
      }
    }
    return dp[m][n];
  }

  List<String> words = text.toLowerCase().split(RegExp('[^a-z]+')).where((w) => w.isNotEmpty).toList();
  if (words.isEmpty) return 0.0;
  int totalEdits = 0;
  for (String word in words) {
    if (corrections.containsKey(word)) {
      totalEdits += editDistance(word, corrections[word]!);
    }
  }
  return totalEdits / words.length.toDouble();
}

