List<int> fn0(List<List<int>> inventory, int threshold) {
  if (inventory.isEmpty || inventory[0].isEmpty) return [];
  int rows = inventory.length, cols = inventory[0].length;
  List<int> demandPos = [], supplyR = [], supplyC = [];
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (inventory[r][c] < threshold) {
        demandPos.add(r * cols + c);
      } else {
        supplyR.add(r);
        supplyC.add(c);
      }
    }
  }
  if (supplyR.isEmpty) return demandPos;
  List<int> dists = [];
  for (int i = 0; i < demandPos.length; i++) {
    int dr = demandPos[i] ~/ cols, dc = demandPos[i] % cols;
    int minD = 999999999;
    for (int j = 0; j < supplyR.length; j++) {
      int d = (dr - supplyR[j]).abs() + (dc - supplyC[j]).abs();
      if (d < minD) minD = d;
    }
    dists.add(minD);
  }
  List<int> idx = List<int>.generate(demandPos.length, (i) => i);
  idx.sort((a, b) => dists[a] != dists[b]
      ? dists[a].compareTo(dists[b])
      : demandPos[a].compareTo(demandPos[b]));
  return idx.map((i) => demandPos[i]).toList();
}

