@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(String encoded) {
  Map<String, String> minuteMap = {
    'A': '00',
    'B': '15',
    'C': '30',
    'D': '45',
  };

  String result = '';
  int checksum = 0;
  int i = 0;

  while (i < encoded.length) {
    int count = 0;
    while (i < encoded.length) {
      int digit = encoded.codeUnitAt(i) - 48;
      if (digit < 0 || digit > 9) {
        break;
      }
      count = count * 10 + digit;
      i++;
    }

    String symbol = encoded[i];
    i++;

    for (int j = 0; j < count; j++) {
      if (symbol == 'E') {
        result += '|';
      } else {
        if (result.isNotEmpty && !result.endsWith('|')) {
          result += ',';
        }
        result += minuteMap[symbol]!;
        checksum = (checksum + int.parse(minuteMap[symbol]!)) % 100;
      }
    }
  }

  String checksumText = checksum.toString().padLeft(2, '0');
  return result + '#' + checksumText;
}

