@pragma('vm:entry-point')
Set<int> fn0(List<String> items, int maxWeight) {
  List<(int, String, int, int)> parsed = [];
  for (int i = 0; i < items.length; i++) {
    List<String> parts = items[i].split(':');
    if (parts.length != 3) throw FormatException('Invalid item format');
    String name = parts[0];
    int weight = int.parse(parts[1]);
    int value = int.parse(parts[2]);
    parsed.add((i, name, weight, value));
  }
  parsed.sort((a, b) {
    double da = a.$3 == 0 ? double.infinity : a.$4 / a.$3;
    double db = b.$3 == 0 ? double.infinity : b.$4 / b.$3;
    int cmp = db.compareTo(da);
    if (cmp != 0) return cmp;
    cmp = a.$3.compareTo(b.$3);
    if (cmp != 0) return cmp;
    return a.$1.compareTo(b.$1);
  });
  Set<int> result = {};
  int currentWeight = 0;
  for (var (index, _, weight, _) in parsed) {
    if (weight <= maxWeight - currentWeight) {
      result.add(index);
      currentWeight += weight;
    }
  }
  return result;
}

