@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(String log) {
  if (log.isEmpty) return "EMPTY";
  List<double> h = [];
  for (String p in log.split(',')) {
    if (p.isEmpty) continue;
    h.add(double.parse(p));
  }
  if (h.length < 2) return "INVALID:short";
  int state = 0; 
  int transitions = 0;
  int anomalies = 0;
  double prev = h[0];
  for (int i = 1; i < h.length; i++) {
    double curr = h[i];
    if (curr > prev) {
      if (state == 2 || state == 4) transitions++;
      state = 1;
    } else if (curr < prev) {
      if (state == 1 || state == 3) transitions++;
      state = 2;
    } else {
      if (state == 1) state = 3;
      else if (state == 2) state = 4;
      else anomalies++;
    }
    if ((state == 1 && curr < prev - 0.25) || (state == 2 && curr > prev + 0.25)) anomalies++;
    prev = curr;
  }
  if (anomalies > 0) return "INVALID:" + anomalies.toString() + "a";
  return "VALID:" + transitions.toString() + "t";
}

