  int rightA = ax2;
  if (leftA > rightA) {
    leftA = ax2;
    rightA = ax1;
  }
  int bottomA = ay1;
  int topA = ay2;
  if (bottomA > topA) {
    bottomA = ay2;
    topA = ay1;
