@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(String tallyString) {
  if (tallyString.isEmpty) return false;
  Map<String, int> totals = {};
  int grandTotal = 0;
  Set<String> seenPrecincts = {};
  for (String p in tallyString.split(';')) {
    int colon = p.indexOf(':');
    if (colon <= 0 || colon == p.length - 1) return false;
    String pName = p.substring(0, colon);
    if (pName.length > 10) return false;
    for (int i = 0; i < pName.length; i++) {
      int c = pName.codeUnitAt(i);
      if (!((c >= 48 && c <= 57) || (c >= 65 && c <= 90) || (c >= 97 && c <= 122))) return false;
    }
    if (seenPrecincts.contains(pName)) return false;
    seenPrecincts.add(pName);
    int precinctTotal = 0;
    Set<String> seenCandidates = {};
    for (String pair in p.substring(colon + 1).split(',')) {
      int pColon = pair.indexOf(':');
      if (pColon <= 0 || pColon == pair.length - 1) return false;
      String cName = pair.substring(0, pColon);
      if (cName.length > 10) return false;
      for (int i = 0; i < cName.length; i++) {
        int c = cName.codeUnitAt(i);
        if (!((c >= 65 && c <= 90) || (c >= 97 && c <= 122))) return false;
      }
      if (seenCandidates.contains(cName)) return false;
      seenCandidates.add(cName);
      String vStr = pair.substring(pColon + 1);
      if (vStr.isEmpty || vStr.length > 4 || (vStr.length > 1 && vStr.startsWith('0'))) return false;
      int votes = 0;
      for (int i = 0; i < vStr.length; i++) {
        int c = vStr.codeUnitAt(i);
        if (c < 48 || c > 57) return false;
        votes = votes * 10 + (c - 48);
      }
      precinctTotal += votes;
      totals[cName] = (totals[cName] ?? 0) + votes;
    }
    if (precinctTotal > 1000) return false;
    grandTotal += precinctTotal;
  }
  if (grandTotal == 0) return false;
  int majorityThreshold = grandTotal ~/ 2;
  return totals.values.where((v) => v > majorityThreshold).length == 1;
}

