bool fn0(List<int> shelfCodes, int bookCode, int maxGap) {
  if (shelfCodes.isEmpty) return false;
  int low = 0;
  int high = shelfCodes.length - 1;
  while (low <= high) {
    int mid = low + (high - low) ~/ 2;
    if (shelfCodes[mid] == bookCode) return true;
    if (shelfCodes[mid] < bookCode) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  int minDist = 1 << 30;
  if (high >= 0) {
    minDist = bookCode - shelfCodes[high];
  }
  if (low < shelfCodes.length) {
    int dist = shelfCodes[low] - bookCode;
    if (dist < minDist) minDist = dist;
  }
  return minDist <= maxGap;
}

