double fn0(List<List<int>> buckets, int limit) {
  if (buckets.isEmpty || buckets[0].isEmpty) {
    return 0.0;
  }

  int score = 0;
  List<List<int>> directions = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1]
  ];

  for (int r = 0; r < buckets.length; r++) {
    for (int c = 0; c < buckets[r].length; c++) {
      int value = buckets[r][c];
      bool touchesSafeBucket = false;
      bool touchesOverloadedBucket = false;

      for (List<int> dir in directions) {
        int nr = r + dir[0];
        int nc = c + dir[1];

        if (nr >= 0 && nr < buckets.length && nc >= 0 && nc < buckets[nr].length) {
          int neighbor = buckets[nr][nc];
          if (neighbor <= limit) {
            touchesSafeBucket = true;
          }
          if (neighbor > limit) {
            touchesOverloadedBucket = true;
          }
        }
      }

      if (value > limit) {
        score += 2;
        if (touchesSafeBucket) {
          score += 1;
        }
      } else if (value == 0 && touchesOverloadedBucket) {
        score += 1;
      }
    }
  }

  return score / 4.0;
}

