List<int> fn0(List<int> log, int capacity) {
  final pending = <int>[];
  final executed = <int>[];
  var total = 0;

  for (final cmd in log) {
    if (cmd > 0) {
      pending.add(cmd);
      total += cmd;
      while (total > capacity && pending.isNotEmpty) {
        total -= pending.removeLast();
      }
    } else if (cmd == 0) {
      if (pending.isNotEmpty) {
        final window = pending.removeLast();
        total -= window;
        executed.add(window);
      }
    } else {
      final target = -cmd;
      for (var i = pending.length - 1; i >= 0; i--) {
        if (pending[i] == target) {
          total -= pending.removeAt(i);
          break;
        }
      }
    }
  }

  return executed;
}

