Set<int> fn0(List<List<int>> trafficGrid, int burstThreshold, int minConsecutive, int smoothingWindow) {
  Set<int> burstyLinks = <int>{};
  for (int linkIndex = 0; linkIndex < trafficGrid.length; linkIndex++) {
    List<int> link = trafficGrid[linkIndex];
    if (link.isEmpty) continue;
    List<int> smoothed = <int>[];
    for (int i = 0; i < link.length; i++) {
      int windowMax = 0;
      for (int j = 0; j < smoothingWindow; j++) {
        int idx = i - j;
        if (idx < 0) break;
        if (link[idx] > windowMax) windowMax = link[idx];
      }
      smoothed.add(windowMax);
    }
    int consecutive = 0;
    for (int value in smoothed) {
      if (value > burstThreshold) {
        consecutive++;
        if (consecutive >= minConsecutive) {
          burstyLinks.add(linkIndex);
          break;
        }
      } else {
        consecutive = 0;
      }
    }
  }
  return burstyLinks;
}

