bool fn0(int shelfCode, int occupiedMask) {
  int slots = shelfCode & 0xFF;
  int weightFlags = (shelfCode >> 8) & 0xFF;

  if (slots == 0) return false;
  if ((slots & occupiedMask) != 0) return false;

  int slotsCount = 0;
  int temp = slots;
  while (temp != 0) {
    slotsCount += temp & 1;
    temp >>= 1;
  }

  int flagsCount = 0;
  temp = weightFlags;
  while (temp != 0) {
    flagsCount += temp & 1;
    temp >>= 1;
  }

  if (slotsCount != flagsCount) return false;

  int lowest = slots & (-slots);
  int normalized = slots ~/ lowest;
  if ((normalized & (normalized + 1)) != 0) return false;

  return true;
}

