double fn0(List<String> shelfCodes, int maxSections) {
  if (shelfCodes.isEmpty || maxSections <= 0) {
    return 0.0;
  }

  Map<String, int> sectionCounts = {};
  int left = 0;
  int pairBonus = 0;
  double best = 0.0;

  for (int right = 0; right < shelfCodes.length; right++) {
    String start = shelfCodes[right][0];
    sectionCounts[start] = (sectionCounts[start] ?? 0) + 1;

    if (right > 0) {
      String currentEnd = shelfCodes[right][shelfCodes[right].length - 1];
      String previousEnd = shelfCodes[right - 1][shelfCodes[right - 1].length - 1];
      if (currentEnd == previousEnd) {
        pairBonus++;
      }
    }

    while (sectionCounts.length > maxSections) {
      if (left < right) {
        String leftEnd = shelfCodes[left][shelfCodes[left].length - 1];
        String nextEnd = shelfCodes[left + 1][shelfCodes[left + 1].length - 1];
        if (leftEnd == nextEnd) {
          pairBonus--;
        }
      }

      String leftStart = shelfCodes[left][0];
      sectionCounts[leftStart] = sectionCounts[leftStart]! - 1;
      if (sectionCounts[leftStart] == 0) {
        sectionCounts.remove(leftStart);
      }
      left++;
    }

    int windowLength = right - left + 1;
    double score = windowLength + (pairBonus / 2.0);
    if (score > best) {
      best = score;
    }
  }

  return best;
}

