import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(List<String> events) {
  final List<Map<String, Object>> history = [];
  final List<int> channelStack = [];
  final Map<int, String> buffers = {};
  Set<int> corrupted = <int>{};

  for (final String event in events) {
    if (event == "UNDO") {
      if (history.isNotEmpty) {
        final Map<String, Object> snapshot = history.removeLast();
        channelStack
          ..clear()
          ..addAll((snapshot['stack'] as List<int>));
        buffers
          ..clear()
          ..addAll((snapshot['buffers'] as Map<int, String>));
        corrupted = Set<int>.from(snapshot['corrupted'] as Set<int>);
      }
      continue;
    }

    history.add({
      'stack': List<int>.from(channelStack),
      'buffers': Map<int, String>.from(buffers),
      'corrupted': Set<int>.from(corrupted),
    });

    if (event.startsWith('OPEN:')) {
      final int id = int.parse(event.substring(5));
      channelStack.add(id);
      buffers[id] = '';
    } else if (event == "." || event == "-") {
      if (channelStack.isNotEmpty) {
        final int id = channelStack.last;
        buffers[id] = buffers[id]! + event;
      }
    } else if (event.startsWith('CLOSE:')) {
      if (channelStack.isNotEmpty) {
        final int id = channelStack.removeLast();
        final String expected = event.substring(6);
        if (buffers[id] != expected) {
          corrupted.add(id);
        }
        buffers.remove(id);
      }
    }
  }

  return corrupted;
}

