import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<int> tracks, int mixShift) {
  int rotateLeft8(int value, int shift) {
    shift &= 7;
    if (shift == 0) {
      return value & 255;
    }
    return ((value << shift) & 255) | ((value & 255) >> (8 - shift));
  }

  int popcount(int value) {
    int count = 0;
    while (value != 0) {
      count += value & 1;
      value >>= 1;
    }
    return count;
  }

  int state = 0;
  int score = 0;

  for (int i = 0; i < tracks.length; i++) {
    int shift = (mixShift + i) & 7;
    int current = rotateLeft8(tracks[i] & 255, shift);

    int shared = popcount(state & current);
    int fresh = popcount(current & (~state & 255));

    if (shared > fresh) {
      score += (shared - fresh) * (i + 1);
    } else {
      score ^= (fresh << 1) | shared;
    }

    if ((current & 1) == 1) {
      state ^= current;
    } else {
      state |= current;
    }
  }

  return score + popcount(state);
}

