List<String> fn0(List<int> chargeLevels, int maxVariance) {
  if (chargeLevels.isEmpty) return [];
  List<int> maxDeque = [];
  List<int> minDeque = [];
  int bestStart = 0;
  int bestLen = 1;
  int left = 0;
  for (int right = 0; right < chargeLevels.length; right++) {
    while (maxDeque.isNotEmpty && chargeLevels[maxDeque.last] <= chargeLevels[right]) {
      maxDeque.removeLast();
    }
    maxDeque.add(right);
    while (minDeque.isNotEmpty && chargeLevels[minDeque.last] >= chargeLevels[right]) {
      minDeque.removeLast();
    }
    minDeque.add(right);
    while (chargeLevels[maxDeque.first] - chargeLevels[minDeque.first] > maxVariance) {
      left++;
      if (maxDeque.first < left) maxDeque.removeAt(0);
      if (minDeque.first < left) minDeque.removeAt(0);
    }
    int currentLen = right - left + 1;
    if (currentLen > bestLen) {
      bestLen = currentLen;
      bestStart = left;
    }
  }
  List<String> result = [];
  for (int i = bestStart; i < bestStart + bestLen; i++) {
    result.add(chargeLevels[i].toString());
  }
  return result;
}

