double fn0(double amount, int originalServings, int desiredServings) {
  int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }
  if (originalServings == 0) return 0.0;
  int g = gcd(originalServings, desiredServings);
  int simOrig = originalServings ~/ g;
  int simDes = desiredServings ~/ g;
  return amount * simDes / simOrig;
}

