bool fn0(List<List<double>> passes, double maxCapacity) {
  if (passes.isEmpty) return true;

  List<Map<String, double>> events = [];
  for (var pass in passes) {
    double start = pass[0];
    double end = pass[1];
    double load = pass[2];
    if (start >= end || load <= 0.0) {
      return false;
    }
    events.add({'time': start, 'change': load});
    events.add({'time': end, 'change': -load});
  }

  events.sort((a, b) {
    if (a['time']! != b['time']!) {
      return (a['time']! < b['time']!) ? -1 : 1;
    }
    return (a['change']! < b['change']!) ? -1 : (a['change']! > b['change']! ? 1 : 0);
  });

  double currentLoad = 0.0;
  for (var event in events) {
    currentLoad += event['change']!;
    if (currentLoad > maxCapacity) {
      return false;
    }
  }

  return true;
}

