import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<String> sortedPixels, List<int> targetBrightnesses) {
  int brightness(String pixel) {
    List<String> parts = pixel.split(',');
    return int.parse(parts[0]) + int.parse(parts[1]) + int.parse(parts[2]);
  }

  List<String> result = [];

  for (int target in targetBrightnesses) {
    if (sortedPixels.isEmpty) {
      result.add('none');
      continue;
    }

    int left = 0;
    int right = sortedPixels.length - 1;

    while (left < right) {
      int mid = (left + right) ~/ 2;
      if (brightness(sortedPixels[mid]) < target) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }

    int bestIndex = left;

    if (left > 0) {
      int currentDiff = (brightness(sortedPixels[left]) - target).abs();
      int previousDiff = (brightness(sortedPixels[left - 1]) - target).abs();

      if (previousDiff < currentDiff) {
        bestIndex = left - 1;
      } else if (previousDiff == currentDiff &&
          sortedPixels[left - 1].compareTo(sortedPixels[left]) < 0) {
        bestIndex = left - 1;
      }
    }

    result.add(sortedPixels[bestIndex]);
  }

  return result;
}

