    int h = r[2];
    if (h <= 0) continue;
    int x = r[0];
    int y = r[1];
    rects.add([x + y - h, x + y + h, x - y - h, x - y + h]);
  }

  if (rects.isEmpty) return 0.0;

  Set<int> xSet = {};
  for (var rect in rects) {
    xSet.add(rect[0]);
    xSet.add(rect[1]);
  }
