String fn0(String asciiArt, int maxGaps) {
  List<String> rows = asciiArt.split('\n');
  List<String> results = [];
  for (int i = 0; i < rows.length; i++) {
    String row = rows[i];
    if (row.isEmpty) {
      results.add('$i:0');
      continue;
    }
    int maxLen = 0;
    int left = 0;
    int spaces = 0;
    for (int right = 0; right < row.length; right++) {
      if (row[right] == ' ') {
        spaces++;
