List<String> fn0(List<String> segments) {
  final String digits = segments.join('').replaceAll(RegExp(r'[^0-9]'), '');
  if (digits.isEmpty) return [];

  final int padLen = (4 - (digits.length % 4)) % 4;
  final String padded = digits + '0' * padLen;

  final List<String> chunks = padded.split('').fold<List<String>>(
    [],
    (List<String> acc, String char) {
      if (acc.isEmpty || acc.last.length == 4) {
        acc.add(char);
      } else {
        acc[acc.length - 1] += char;
      }
      return acc;
    },
  );

  return chunks.map((String chunk) {
    final List<int> weights = [3, 1, 3, 1];
    int sum = 0;
    for (int i = 0; i < 4; i++) {
      sum += (chunk.codeUnitAt(i) - 48) * weights[i];
    }
    final int check = (10 - (sum % 10)) % 10;
    return '$chunk$check';
  }).toList();
}

