List<int> fn0(List<List<int>> grid) {
  if (grid.isEmpty) return [];
  final rows = grid.length;
  final cols = grid[0].length;
  final result = <int>[];
  int runningSum = 0;
  for (int i = 0; i < rows; i++) {
    if (i % 2 == 0) {
      for (int j = 0; j < cols; j++) {
        int val = grid[i][j];
        final border = (i == 0 || i == rows - 1 || j == 0 || j == cols - 1);
        if (border) {
          val *= 2;
        } else if (i == j || i + j == cols - 1) {
          val *= 3;
        }
        runningSum += val;
        result.add(runningSum);
      }
    } else {
      for (int j = cols - 1; j >= 0; j--) {
        int val = grid[i][j];
        final border = (i == 0 || i == rows - 1 || j == 0 || j == cols - 1);
        if (border) {
          val *= 2;
        } else if (i == j || i + j == cols - 1) {
          val *= 3;
        }
        runningSum += val;
        result.add(runningSum);
      }
    }
  }
  return result;
}

