Map<String, int> fn0(List<int> roundDays, int cooldown) {



  final days = List<int>.from(roundDays)..sort();
  var played = 0;
  var forfeited = 0;
  var longestGap = 0;
  var firstPlayed = 0;
  var lastPlayed = 0;
  var hasPlayed = false;
  for (final d in days) {
    if (!hasPlayed) {
      hasPlayed = true;
      played = 1;
      firstPlayed = d;
      lastPlayed = d;
    } else if (d - lastPlayed > cooldown) {
      final gap = d - lastPlayed;
      if (gap > longestGap) longestGap = gap;
      played++;
      lastPlayed = d;
    } else {
      forfeited++;
    }
  }
  final span = hasPlayed ? lastPlayed - firstPlayed : 0;
  final restDays = played > 1 ? span - (played - 1) : 0;
  return {
    'played': played,
    'forfeited': forfeited,
    'span': span,
    'longestGap': longestGap,
    'restDays': restDays,
  };
}

