import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<int> precinctVotes, int base) {
  if (base < 2 || base > 16) {
    return <String>[];
  }

  int gcdValue(int a, int b) {
    a = a.abs();
    b = b.abs();
    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  int largestPrimeFactor(int n) {
    if (n <= 1) {
      return 1;
    }
    int factor = 1;
    while (n % 2 == 0) {
      factor = 2;
      n ~/= 2;
    }
    int d = 3;
    while (d * d <= n) {
      while (n % d == 0) {
        factor = d;
        n ~/= d;
      }
      d += 2;
    }
    return n > 1 ? n : factor;
  }

  String toBase(int value, int radix) {
    const digits = '0123456789ABCDEF';
    if (value == 0) {
      return '0';
    }
    String out = '';
    int n = value;
    while (n > 0) {
      out = digits[n % radix] + out;
      n ~/= radix;
    }
    return out;
  }

  int globalGcd = 0;
  for (final votes in precinctVotes) {
    globalGcd = gcdValue(globalGcd, votes);
  }

  List<String> result = <String>[];
  for (final votes in precinctVotes) {
    int normalized = globalGcd == 0 ? 0 : votes.abs() ~/ globalGcd;
    int factor = largestPrimeFactor(normalized);

    int reduced = factor;
    while (reduced > 1 && gcdValue(reduced, base) != 1) {
      reduced ~/= gcdValue(reduced, base);
    }

    int period = 0;
    if (reduced > 1) {
      int residue = base % reduced;
      period = 1;
      while (residue != 1) {
        residue = (residue * base) % reduced;
        period++;
      }
    }

    result.add('${toBase(normalized, base)}:$factor:$period');
  }

  return result;
}

