int fn0(String password) {
  if (password.isEmpty) {
    return 0;
  }

  List<int> position(String ch) {
    switch (ch) {
      case '1': return [0, 0];
      case '2': return [1, 0];
      case '3': return [2, 0];
      case '4': return [0, 1];
      case '5': return [1, 1];
      case '6': return [2, 1];
      case '7': return [0, 2];
      case '8': return [1, 2];
      case '9': return [2, 2];
      default: return [1, 3];
    }
  }

  int score = 0;
  Set<String> visited = {};
  List<int> first = position(password[0]);
  visited.add('${first[0]},${first[1]}');

  for (int i = 1; i < password.length; i++) {
    List<int> prev = position(password[i - 1]);
    List<int> curr = position(password[i]);
    int dx = (curr[0] - prev[0]).abs();
    int dy = (curr[1] - prev[1]).abs();

    score += dx + dy;

    if (dx > 0 && dy > 0) {
      score += 1;
    }

    String key = '${curr[0]},${curr[1]}';
    if (visited.contains(key)) {
      score += 4;
    } else {
      visited.add(key);
    }

    if (i >= 2) {
      List<int> prev2 = position(password[i - 2]);
      if ((prev2[0] == prev[0] && prev[0] == curr[0]) ||
          (prev2[1] == prev[1] && prev[1] == curr[1])) {
        score += 2;
      }
    }
  }

  return score;
}

