import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(List<String> barcodes) {
  if (barcodes.isEmpty) return '';

  int transitionScore(String barcode) {
    int score = 0;
    for (int i = 0; i < barcode.length - 1; i++) {
      int d1 = int.parse(barcode[i]);
      int d2 = int.parse(barcode[i + 1]);
      int diff = (d2 - d1).abs();
      if (diff == 0) {
        score -= 1;
      } else if (diff == 1) {
        score += 3;
      } else if (diff <= 3) {
        score += 1;
      } else {
        score -= 2;
      }
    }
    return score;
  }

  int parityAlternations(String barcode) {
    int count = 0;
    for (int i = 0; i < barcode.length - 1; i++) {
      bool even1 = int.parse(barcode[i]) % 2 == 0;
      bool even2 = int.parse(barcode[i + 1]) % 2 == 0;
      if (even1 != even2) count++;
    }
    return count;
  }

  List<String> sorted = List<String>.from(barcodes);
  sorted.sort((String a, String b) {
    int tA = transitionScore(a);
    int tB = transitionScore(b);
    if (tA != tB) return tB.compareTo(tA);

    int pA = parityAlternations(a);
    int pB = parityAlternations(b);
    if (pA != pB) return pB.compareTo(pA);

    int lenCmp = a.length.compareTo(b.length);
    if (lenCmp != 0) return lenCmp;

    return a.compareTo(b);
  });

  return sorted.join('-');
}

