@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<List<double>> grid) {
  final Map<String, int> counts = {};
  for (final row in grid) {
    for (final moisture in row) {
      String zone;
      if (moisture < 0.25) {
        zone = 'arid';
      } else if (moisture < 0.5) {
        zone = 'dry';
      } else if (moisture < 0.75) {
        zone = 'optimal';
      } else if (moisture < 1.0) {
        zone = 'wet';
      } else {
        zone = 'saturated';
      }
      counts[zone] = (counts[zone] ?? 0) + 1;
    }
  }
  if (counts.isEmpty) return [];
  final int total = counts.values.fold(0, (sum, c) => sum + c);
  final int distinct = counts.length;
  final entries = counts.entries.toList();
  entries.sort((a, b) {
    final cmp = b.value.compareTo(a.value);
    return cmp != 0 ? cmp : a.key.compareTo(b.key);
  });
  final List<String> result = [];
  for (final entry in entries) {
    final bool isDominant = entry.value * distinct > total * 2;
    final prefix = isDominant ? '*' : '';
    result.add('$prefix${entry.key}: ${entry.value}');
  }
  return result;
}

