import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<List<int>> board, int startRow, int startCol) {
  if (board.isEmpty || board[0].isEmpty) return 0.0;
  if (startRow < 0 || startRow >= board.length || startCol < 0 || startCol >= board[0].length) {
    return 0.0;
  }
  if (board[startRow][startCol] == 1000) return 0.0;

  int rows = board.length;
  int cols = board[0].length;
  List<List<int>> dist = List.generate(rows, (_) => List.filled(cols, 1000));
  List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));

  dist[startRow][startCol] = 0;

  final List<int> dr = [-2, -2, -1, -1, 1, 1, 2, 2];
  final List<int> dc = [-1, 1, -2, 2, -2, 2, -1, 1];

  for (int step = 0; step < rows * cols; step++) {
    int minDist = 1000;
    int minR = -1, minC = -1;

    for (int r = 0; r < rows; r++) {
      for (int c = 0; c < cols; c++) {
        if (!visited[r][c] && dist[r][c] < minDist) {
          minDist = dist[r][c];
          minR = r;
          minC = c;
        }
      }
    }

    if (minR == -1) break;
    visited[minR][minC] = true;

    for (int i = 0; i < 8; i++) {
      int nr = minR + dr[i];
      int nc = minC + dc[i];
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
        int cost = (board[nr][nc] == 1000) ? 1001 : 1;
        if (dist[minR][minC] + cost < dist[nr][nc]) {
          dist[nr][nc] = dist[minR][minC] + cost;
        }
      }
    }
  }

  double score = 0.0;
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (dist[r][c] < 1000) {
        score += 1.0 / (1 << dist[r][c]);
      }
    }
  }
  return score;
}

