import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(String grid) {
  if (grid.trim().isEmpty) return "R0:C0:AVG0.0:DRY0:WET0";
  List<String> rows = grid.split('|');
  int rowCount = 0, maxCols = 0, cellCount = 0, dryCount = 0, wetCount = 0;
  double totalMoisture = 0.0;
  for (String row in rows) {
    String cleanedRow = row.replaceAll(RegExp(r'<[^>]*>'), '').trim();
    if (cleanedRow.isEmpty) continue;
    List<String> cells = cleanedRow.split(',');
    int colCount = 0;
    for (String cell in cells) {
      String cleaned = cell.trim();
      if (cleaned.isEmpty) continue;
      double moisture;
      if (cleaned == 'D') { moisture = 0.0; }
      else if (cleaned == 'W') { moisture = 10.0; }
      else if (cleaned == 'E') { continue; }
      else {
        double? parsed = double.tryParse(cleaned);
        if (parsed == null || parsed < 0.0 || parsed > 10.0) continue;
        moisture = parsed;
      }
      colCount++;
      totalMoisture += moisture;
      cellCount++;
      if (moisture <= 2.0) dryCount++;
      if (moisture >= 8.0) wetCount++;
    }
    if (colCount > 0) { rowCount++; if (colCount > maxCols) maxCols = colCount; }
  }
  double avg = cellCount > 0 ? (totalMoisture / cellCount) : 0.0;
  avg = (avg * 4.0).roundToDouble() / 4.0;
  return "R$rowCount:C$maxCols:AVG$avg:DRY$dryCount:WET$wetCount";
}

