@pragma('vm:entry-point')
String fn0(List<int> schedule, int maxChange) {
  if (schedule.isEmpty) {
    return '';
  }

  List<int>? best;
  int bestCost = 1 << 30;
  List<int> current = List<int>.filled(schedule.length, 0);

  bool lexicographicallySmaller(List<int> a, List<int> b) {
    for (int i = 0; i < a.length; i++) {
      if (a[i] != b[i]) {
        return a[i] < b[i];
      }
    }
    return false;
  }

  void search(int index, int cost) {
    if (cost > bestCost) {
      return;
    }

    if (index == schedule.length) {
      if (best == null || cost < bestCost ||
          (cost == bestCost && lexicographicallySmaller(current, best!))) {
        best = List<int>.from(current);
        bestCost = cost;
      }
      return;
    }

    List<int> options = schedule[index] == -1
        ? [60, 61, 62, 63, 64, 65, 66, 67, 68, 69, 70, 71, 72]
        : [schedule[index]];

    for (int value in options) {
      if (index > 0) {
        int diff = (value - current[index - 1]).abs();
        if (diff > maxChange) {
          continue;
        }
        current[index] = value;
        search(index + 1, cost + diff);
      } else {
        current[index] = value;
        search(index + 1, 0);
      }
    }
  }

  search(0, 0);

  if (best == null) {
    return 'IMPOSSIBLE';
  }

  return best!.join(',');
}

