Set<int> fn0(List<int> energy, int budget, int minLength) {
  Set<int> result = {};
  if (energy.isEmpty || minLength > energy.length) {
    return result;
  }
  int left = 0;
  int sum = 0;
  int blockStart = -1;
  int blockEnd = -1;
  for (int right = 0; right < energy.length; right++) {
    sum += energy[right];
    while (sum > budget && left <= right) {
      sum -= energy[left];
      left++;
