Set<int> fn0(String stream) {
  Set<int> result = {};
  int state = 0;
  int dataSum = 0;
  int digitCount = 0;
  int checkDigit = -1;

  for (int i = 0; i < stream.length; i++) {
    String c = stream[i];
    if (c == 'X') {
      state = 0;
      dataSum = 0;
      digitCount = 0;
      continue;
    }
    switch (state) {
      case 0:
        if (c == 'B') {
          state = 1;
          dataSum = 0;
          digitCount = 0;
