        if (code2 >= 48 && code2 <= 57) {
          checkDigit = code2 - 48;
          state = 3;
        } else {
          state = 0;
        }
        break;
      case 3:
        if (c == 'E' && checkDigit == dataSum % 10) {
          result.add(checkDigit);
        }
        state = 0;
        dataSum = 0;
        digitCount = 0;
        break;
    }
  }
  return result;
}

