  int i = 0;
  while (i < program.length) {
    String c = program[i];
    if (c == 'H') {
      hold = true;
      i++;
    } else if (c == 'R') {
      hold = false;
      i++;
    } else if (c == 'S' || c == '+' || c == '-') {
      i++;
      int start = i;
      while (i < program.length &&
          program.codeUnitAt(i) >= 48 &&
