      if (start == i) return -1;
      int value = int.parse(program.substring(start, i));
      if (!hold) {
        if (c == 'S') {
          temp = value;
        } else if (c == '+') {
          temp += value;
        } else {
          temp -= value;
        }
      }
    } else {
      return -1;
    }
  }
  return temp;
}

