String fn0(List<int> heights) {
  if (heights.isEmpty) return '';
  int maxH = heights.reduce((a, b) => a > b ? a : b);

  List<String> rows = [];
  for (int level = maxH; level >= 1; level--) {
    String row = heights.map((h) => h >= level ? '#' : ' ').join();
    rows.add(row);
  }

  List<String> deduped = [];
  int i = 0;
  while (i < rows.length) {
    String current = rows[i];
    int count = 1;
    while (i + count < rows.length && rows[i + count] == current) {
      count++;
    }
    if (count > 1) {
      deduped.add('$current ×$count');
    } else {
      deduped.add(current);
    }
    i += count;
  }

  return deduped.join('\n');
}

