import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(String typed, String correct) {
  final n = typed.length;
  final m = correct.length;
  final dp = List.generate(n + 1, (_) => List<int>.filled(m + 1, 0));
  for (var i = 0; i <= n; i++) {
    dp[i][0] = i;
  }
  for (var j = 0; j <= m; j++) {
    dp[0][j] = j;
  }
  for (var i = 1; i <= n; i++) {
    for (var j = 1; j <= m; j++) {
      if (typed[i - 1] == correct[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        var best = dp[i - 1][j - 1];
        if (dp[i - 1][j] < best) best = dp[i - 1][j];
        if (dp[i][j - 1] < best) best = dp[i][j - 1];
        dp[i][j] = best + 1;
      }
    }
  }

  final ops = StringBuffer();
  var i = n;
  var j = m;
  while (i > 0 || j > 0) {
    if (i > 0 &&
        j > 0 &&
        typed[i - 1] == correct[j - 1] &&
        dp[i][j] == dp[i - 1][j - 1]) {
      ops.write('K');
      i--;
      j--;
    } else if (i > 0 && j > 0 && dp[i][j] == dp[i - 1][j - 1] + 1) {
      ops.write('S');
      i--;
      j--;
    } else if (i > 0 && dp[i][j] == dp[i - 1][j] + 1) {
      ops.write('D');
      i--;
    } else {
      ops.write('I');
      j--;
    }
  }
  return ops.toString().split('').reversed.join();
}

