import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> fn0(int totalSeats, int numViewers, List<int> blocked) {
  bool canPlace(int d) {
    int count = 0;
    int last = -d;
    List<int> bl = List.from(blocked)..sort();
    int bi = 0;
    for (int s = 1; s <= totalSeats; s++) {
      while (bi < bl.length && bl[bi] < s) bi++;
      if (bi < bl.length && bl[bi] == s) continue;
      if (s - last >= d) {
        count++;
        last = s;
      }
    }
    return count >= numViewers;
  }

  int low = 1, high = totalSeats, best = 1;
  while (low <= high) {
    int mid = (low + high) ~/ 2;
    if (canPlace(mid)) {
      best = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  Set<int> chosen = {};
  int last = -best;
  List<int> bl = List.from(blocked)..sort();
  int bi = 0;
  for (int s = 1; s <= totalSeats && chosen.length < numViewers; s++) {
    while (bi < bl.length && bl[bi] < s) bi++;
    if (bi < bl.length && bl[bi] == s) continue;
    if (s - last >= best) {
      chosen.add(s);
      last = s;
    }
  }
  return chosen;
}

