bool fn0(List<int> current, List<int> target) {
  int n = current.length;
  int m = target.length;
  List<List<bool>> dp = List.generate(n + 1, (i) => List.filled(m + 1, false));
  dp[0][0] = true;

  for (int i = 1; i <= n; i++) {
    for (int j = 0; j <= m; j++) {
      if (current[i - 1] == 0) {
        dp[i][j] = dp[i - 1][j];
      }
      int sum = 0;
      for (int p = j - 1; p >= 0; p--) {
        sum += target[p];
        if (sum == current[i - 1] && dp[i - 1][p]) {
          dp[i][j] = true;
          break;
        } else if (sum > current[i - 1]) {
          break;
        }
      }
    }
  }
  return dp[n][m];
}

