  if (rarities.isEmpty || maxDistinct <= 0) return 'none';
  Map<int, int> counts = {};
  int left = 0;
  int bestStart = 0;
  int bestLen = 0;
  for (int right = 0; right < rarities.length; right++) {
    counts[rarities[right]] = (counts[rarities[right]] ?? 0) + 1;
    while (counts.length > maxDistinct) {
      int r = rarities[left];
      counts[r] = counts[r]! - 1;
      if (counts[r] == 0) {
        counts.remove(r);
      }
      left++;
    }
    int len = right - left + 1;
    if (len > bestLen) {
      bestLen = len;
      bestStart = left;
    }
  }
  return '$bestStart-${bestStart + bestLen - 1}:$bestLen';
}

