Map<String, int> fn0(List<String> itemNames, List<int> values, List<int> weights, int budget) {
  int n = itemNames.length;
  if (n == 0 || budget <= 0) return {};
  List<List<int>> dp = List.generate(n + 1, (_) => List.filled(budget + 1, 0));
  for (int i = 1; i <= n; i++) {
    for (int w = 0; w <= budget; w++) {
      dp[i][w] = dp[i - 1][w];
      if (weights[i - 1] <= w) {
        int fn0 = dp[i - 1][w - weights[i - 1]] + values[i - 1];
        if (fn0 > dp[i][w]) dp[i][w] = fn0;
      }
    }
  }
  Map<String, int> result = {};
  int w = budget;
  for (int i = n; i > 0; i--) {
    if (dp[i][w] != dp[i - 1][w]) {
      result[itemNames[i - 1]] = 1;
      w -= weights[i - 1];
    } else {
      result[itemNames[i - 1]] = 0;
    }
  }
  return result;
}

