List<int> fn0(String phases) {
  const standard = {'R': 3, 'A': 1, 'G': 4, 'Y': 2};
  const cycle = ['R', 'A', 'G', 'Y'];
  if (phases.isEmpty) {
    return [];
  }
  final result = <int>[];
  final lastDuration = <String, int>{};
  int index = 0;
  int runIndex = 0;
  int cycleOffset = 0;
  while (index < phases.length) {
    final char = phases[index];
    final baseStandard = standard[char];
    if (baseStandard == null) {
      return [-1];
    }
    int end = index;
    while (end < phases.length && phases[end] == char) {
      end++;
    }
    final count = end - index;
    if (runIndex == 0) {
      cycleOffset = cycle.indexOf(char);
    }
    final expected = cycle[(cycleOffset + runIndex) % 4];
    if (char != expected) {
      return [-1];
    }
    final base = lastDuration.containsKey(char) ? lastDuration[char]! : baseStandard;
    result.add(count - base);
    lastDuration[char] = count;
    index = end;
    runIndex++;
  }
  int checksum = 0;
  for (final delta in result) {
    checksum = (checksum * 31 + delta) & 0xFFFF;
  }
  result.add(checksum);
  return result;
}

