@pragma('vm:never-inline')
@pragma('vm:entry-point')
String fn0(List<List<int>> cycles) {
  if (cycles.isEmpty || cycles[0].isEmpty) {
    return '';
  }

  int rows = cycles.length;
  int cols = cycles[0].length;
  List<String> bands = [];

  String classify(int value) {
    if (value < 30) {
      return 'D';
    }
    if (value <= 80) {
      return 'S';
    }
    return 'O';
  }

  int top = 0;
  int bottom = rows - 1;
  int left = 0;
  int right = cols - 1;
  int layer = 0;

  while (top <= bottom && left <= right) {
    if (layer % 2 == 0) {
      for (int c = left; c <= right; c++) {
        bands.add(classify(cycles[top][c]));
      }
      for (int r = top + 1; r <= bottom; r++) {
        bands.add(classify(cycles[r][right]));
      }
      if (top < bottom) {
        for (int c = right - 1; c >= left; c--) {
          bands.add(classify(cycles[bottom][c]));
        }
      }
      if (left < right) {
        for (int r = bottom - 1; r > top; r--) {
          bands.add(classify(cycles[r][left]));
        }
      }
    } else {
      for (int r = top; r <= bottom; r++) {
        bands.add(classify(cycles[r][left]));
      }
      for (int c = left + 1; c <= right; c++) {
        bands.add(classify(cycles[bottom][c]));
      }
      if (left < right) {
        for (int r = bottom - 1; r >= top; r--) {
          bands.add(classify(cycles[r][right]));
        }
      }
      if (top < bottom) {
        for (int c = right - 1; c > left; c--) {
          bands.add(classify(cycles[top][c]));
        }
      }
    }

    top++;
    bottom--;
    left++;
    right--;
    layer++;
  }

  String result = '';
  String current = bands[0];
  int count = 1;

  for (int i = 1; i < bands.length; i++) {
    if (bands[i] == current) {
      count++;
    } else {
      result += current + count.toString();
      current = bands[i];
      count = 1;
    }
  }

  result += current + count.toString();
  return result;
}

