double fn0(String shelfMap) {
  double total = 0.0;
  List<String> sections = [];
  String current = '';
  int bracketDepth = 0;

  for (int i = 0; i < shelfMap.length; i++) {
    String ch = shelfMap[i];
    if (ch == '[') bracketDepth++;
    if (ch == ']') bracketDepth--;
    if (ch == ';' && bracketDepth == 0) {
      sections.add(current);
      current = '';
    } else {
      current += ch;
    }
  }
  sections.add(current);

  for (String section in sections) {
    if (section.trim().isEmpty) continue;
    int colon = section.indexOf(':');
    if (colon == -1) {
      total -= 0.5;
      continue;
    }

    String body = section.substring(colon + 1);
    List<String> tokens = [];
    current = '';
    bracketDepth = 0;

    for (int i = 0; i < body.length; i++) {
      String ch = body[i];
      if (ch == '[') bracketDepth++;
      if (ch == ']') bracketDepth--;
      if (ch == ',' && bracketDepth == 0) {
        tokens.add(current.trim());
        current = '';
      } else {
        current += ch;
      }
    }
    tokens.add(current.trim());

    for (String token in tokens) {
      if (token.isEmpty) {
        total -= 0.25;
        continue;
      }

      String lead = token[0];
      if (lead == 'A') {
        total += 1.0;
      } else if (lead == 'B') {
        total += 0.5;
      } else if (lead == 'C') {
        total += 0.25;
      } else {
        total -= 0.25;
      }

      int pos = 1;
      String digits = '';
      while (pos < token.length) {
        String ch = token[pos];
        if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
          digits += ch;
          pos++;
        } else {
          break;
        }
      }

      if (digits.isEmpty) {
        total -= 0.5;
      } else {
        int value = int.parse(digits);
        total += value.isEven ? 0.25 : -0.25;
      }

      int open = token.indexOf('[');
      int close = token.lastIndexOf(']');
      if (open != -1 && close > open) {
        String inner = token.substring(open + 1, close);
        for (String label in inner.split('|')) {
          total += label.length.isEven ? 0.25 : -0.25;
        }
      }
    }
  }

  return total;
}

