      insideSample = contentLengths.isNotEmpty;
    } else if (ch == '!') {
      if (!insideSample) return false;
      contentLengths[contentLengths.length - 1]++;
    } else {
      if (contentLengths.isNotEmpty) {
        contentLengths[contentLengths.length - 1]++;
      }
    }
  }
  return contentLengths.isEmpty;
}

