      if (old.codeUnitAt(0) >= 48 && old.codeUnitAt(0) <= 57) digit--;
    }
    if (i >= windowSize - 1 && upper > 0 && digit > 0) {
      result.add(i - windowSize + 1);
    }
  }
  return result;
}

