int fn0(String encoded) {
  const int mod = 9973;
  int checksum = 0;
  int pos = 0;
  int i = 0;

  while (i < encoded.length) {
    int code = encoded.codeUnitAt(i);

    if (code == 33) {

      if (i + 1 < encoded.length) {
        int litCode = encoded.codeUnitAt(i + 1);
        checksum = (checksum + litCode * (pos + 1)) % mod;
        pos++;
        i += 2;
      } else {

        checksum = (checksum + 33 * (pos + 1)) % mod;
        pos++;
        i++;
      }
    } else if (code >= 65 && code <= 90) {

      if (i + 1 < encoded.length) {
        int nextCode = encoded.codeUnitAt(i + 1);
        if (nextCode >= 48 && nextCode <= 57) {
          int count = nextCode - 48;
          for (int j = 0; j < count; j++) {
            checksum = (checksum + code * (pos + 1)) % mod;
            pos++;
          }
          i += 2;
        } else {
          checksum = (checksum + code * (pos + 1)) % mod;
          pos++;
          i++;
        }
      } else {
        checksum = (checksum + code * (pos + 1)) % mod;
        pos++;
        i++;
      }
    } else {

      checksum = (checksum + code * (pos + 1)) % mod;
      pos++;
      i++;
    }
  }

  return checksum;
}

