@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<String> artRows) {
  final int n = artRows.length;
  final List<int> dp = List<int>.filled(n, 0);
  final List<int> lefts = List<int>.filled(n, -1);
  final List<int> rights = List<int>.filled(n, -1);
  final List<int> widths = List<int>.filled(n, 0);

  for (int i = 0; i < n; i++) {
    final String row = artRows[i];
    int l = -1;
    int r = -1;
    for (int j = 0; j < row.length; j++) {
      if (row[j] == '#') {
        if (l == -1) l = j;
        r = j;
      }
    }
    if (l != -1) {
      lefts[i] = l;
      rights[i] = r;
      widths[i] = r - l + 1;
    }
  }

  for (int i = 0; i < n; i++) {
    if (widths[i] == 0) continue;
    int best = 0;
    for (int j = 0; j < i; j++) {
      if (widths[j] > 0 && lefts[j] <= lefts[i] && rights[j] >= rights[i]) {
        if (dp[j] > best) best = dp[j];
      }
    }
    dp[i] = best + widths[i];
  }

  return dp;
}

