int fn0(String s, int maxSpecial) {
  int maxLen = 0, left = 0, spec = 0, dig = 0, upper = 0;
  for (int right = 0; right < s.length; right++) {
    int c = s.codeUnitAt(right);
    if (c == 32) {
      left = right + 1;
      spec = dig = upper = 0;
      continue;
    }
    bool isD = c >= 48 && c <= 57;
    bool isU = c >= 65 && c <= 90;
    bool isL = c >= 97 && c <= 122;
    if (isD) dig++;
    else if (isU) upper++;
    else if (!isL) spec++;

    while (spec > maxSpecial && left <= right) {
      int lc = s.codeUnitAt(left);
      bool lIsD = lc >= 48 && lc <= 57;
      bool lIsU = lc >= 65 && lc <= 90;
      bool lIsL = lc >= 97 && lc <= 122;
      if (lIsD) dig--;
      else if (lIsU) upper--;
      else if (!lIsL) spec--;
      left++;
    }
    if (dig >= 1 && upper >= 1) {
      int currentLen = right - left + 1;
      if (currentLen > maxLen) {
        maxLen = currentLen;
      }
    }
  }
  return maxLen;
}

