    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    return a.abs();
  }

  int modPow(int base, int exponent, int mod) {
    int result = 1 % mod;
    int value = base % mod;
    int exp = exponent;

    while (exp > 0) {
      if (exp.isOdd) {
        result = (result * value) % mod;
      }
      value = (value * value) % mod;
      exp ~/= 2;
    }

    return result;
  }

  if (!isPrime(primeMod) || primeMod <= 2) {
    return -1.0;
  }

  int total = 0;

  for (final pixel in pixels) {
    int r = (pixel >> 16) & 255;
    int g = (pixel >> 8) & 255;
    int b = pixel & 255;

    int residueBase = (r * 3 + g * 5 + b * 7 + 1) % primeMod;
    int exponent = gcd(r + 1, b + 1) + (g % 3);
    int residue = modPow(residueBase, exponent, primeMod);

    if (((r ^ g ^ b) & 1) == 0) {
      total += residue;
    } else {
      total -= residue;
    }
  }

  return total / 2.0;
}

