  for (String track in tracks) {
    List<String> parts = track.split(',');
    if (parts.length != 3) continue;

    String artist = parts[0];
    String durationStr = parts[2];

    if (!artist.contains(' ')) continue;

    List<String> timeParts = durationStr.split(':');
    if (timeParts.length != 2) continue;
    if (timeParts[1].length != 2) continue;

    int? minutes = int.tryParse(timeParts[0]);
    int? seconds = int.tryParse(timeParts[1]);

    if (minutes == null || seconds == null) continue;

    int totalSeconds = minutes * 60 + seconds;
    if (totalSeconds > 180) {
      count++;
    }
  }
  return count;
}

