import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(String input) {
  if (input.isEmpty) return false;

  final tokens = <String>[];
  final buffer = StringBuffer();

  for (int i = 0; i < input.length; i++) {
    final ch = input[i];
    if (ch == ' ' || ch == ',') {
      if (buffer.isNotEmpty) {
        tokens.add(buffer.toString());
        buffer.clear();
      }
      continue;
    }
    if (ch == '-' || ch == '.' || (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57)) {
      buffer.write(ch);
    } else {
      return false;
    }
  }

  if (buffer.isNotEmpty) {
    tokens.add(buffer.toString());
  }

  if (tokens.isEmpty) return false;

  const maxCents = 1000000000;

  for (final token in tokens) {
    final dollarStr = token;

    if (dollarStr.contains(RegExp(r'[^0-9.\-]'))) continue;
    if (dollarStr.startsWith('-') && dollarStr.length == 1) continue;
    if (dollarStr == '-0' || dollarStr == '-0.0' || dollarStr == '-0.00') continue;

    final parts = dollarStr.split('.');
    if (parts.length > 2) continue;

    String intPart = parts[0];
    String fracPart = parts.length == 2 ? parts[1] : '';

    if (intPart.isEmpty || intPart == '-') continue;
    if (fracPart.length > 2) fracPart = fracPart.substring(0, 2);
    fracPart = fracPart.padRight(2, '0');

    final isNeg = intPart.startsWith('-');
    if (isNeg) intPart = intPart.substring(1);

    final intValue = int.tryParse(intPart);
    final fracValue = int.tryParse(fracPart);

    if (intValue == null || fracValue == null) continue;

    final totalCents = intValue * 100 + fracValue;
    if (totalCents > maxCents) continue;

    final preciseDollars = totalCents / 100.0;
    final doubleFromLiteral = (isNeg ? -1 : 1) * (intValue + fracValue / 100.0);

    if (preciseDollars != doubleFromLiteral) {
      return true;
    }
  }

  return false;
}

