List<int> fn0(String manifest) {
  if (manifest.isEmpty) {
    return <int>[];
  }

  List<int> results = <int>[];
  List<String> batches = manifest.split(';');

  for (String batch in batches) {
    if (batch.isEmpty) {
      continue;
    }

    List<String> parts = batch.split('|');
    if (parts.length != 3) {
      results.add(-1);
      continue;
    }

    String encodedName = parts[0];
    String rle = parts[1];
    int expected = int.tryParse(parts[2]) ?? -1;

    String decoded = '';
    int nameScore = 0;
    for (int i = 0; i < encodedName.length; i++) {
      int code = encodedName.codeUnitAt(i);
      int shifted = code == 97 ? 122 : code - 1;
      decoded += String.fromCharCode(shifted);
      nameScore += shifted - 96;
    }

    int total = 0;
    int count = 0;
    bool valid = true;

    for (int i = 0; i < rle.length; i++) {
      int code = rle.codeUnitAt(i);

      if (code >= 48 && code <= 57) {
        count = count * 10 + (code - 48);
      } else {
        if (count == 0 && (i == 0 || !(rle.codeUnitAt(i - 1) >= 48 && rle.codeUnitAt(i - 1) <= 57))) {
          valid = false;
          break;
        }

        int value;
        if (code >= 65 && code <= 90) {
          value = code - 64;
        } else if (code >= 97 && code <= 122) {
          value = code - 70;
        } else {
          valid = false;
          break;
        }

        total += count * value;
        count = 0;
      }
    }

    if (count != 0) {
      valid = false;
    }

    int checksum = (total + decoded.length + nameScore) % 97;
    results.add(valid && checksum == expected ? total : -1);
  }

  return results;
}

