List<String> fn0(String tape) {
  List<String> result = [];
  String precinct = '';
  String fn0 = '';
  String number = '';
  Map<String, int> totals = {};
  int state = 0;
  bool invalid = false;

  void finishPrecinct() {
    if (invalid || precinct.isEmpty || totals.isEmpty) {
      return;
    }
    String winner = '';
    int best = -1;
    for (String key in totals.keys) {
      int votes = totals[key]!;
      if (votes > best || (votes == best && key.compareTo(winner) < 0)) {
        winner = key;
        best = votes;
      }
    }
    result.add('$precinct:$winner=$best');
  }

  for (int i = 0; i < tape.length; i++) {
    String ch = tape[i];

    if (state == 0) {
      if (ch == '[') {
        precinct = '';
        totals = {};
        invalid = false;
        state = 1;
      }
    } else if (state == 1) {
      if (ch == ':') {
        state = precinct.isEmpty ? 0 : 2;
      } else if (ch.codeUnitAt(0) >= 65 && ch.codeUnitAt(0) <= 90) {
        precinct += ch;
      } else {
        invalid = true;
      }
    } else if (state == 2) {
      if (ch.codeUnitAt(0) >= 65 && ch.codeUnitAt(0) <= 90) {
        fn0 = ch;
        number = '';
        state = 3;
      } else if (ch == ']') {
        finishPrecinct();
        state = 0;
      } else {
        invalid = true;
      }
    } else if (state == 3) {
      if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
        number += ch;
      } else if (ch == ',' || ch == ']') {
        if (number.isEmpty) {
          invalid = true;
        } else {
          totals[fn0] = (totals[fn0] ?? 0) + int.parse(number);
        }
        if (ch == ',') {
          state = 2;
        } else {
          finishPrecinct();
          state = 0;
        }
      } else {
        invalid = true;
      }
    }
  }

  return result;
}

