double fn0(int code) {
  if (code <= 1) return 0.0;

  List<int> divisors = [];
  for (int i = 2; i * i <= code; i++) {
    if (code % i == 0) {
      divisors.add(i);
      int complement = code ~/ i;
      if (complement != i) {
        divisors.add(complement);
      }
    }
  }
  divisors.add(code);

  int modSum = 0;
  for (int d in divisors) {
    int temp = d;
    int largestPrime = 1;

    if (temp % 2 == 0) {
      largestPrime = 2;
      while (temp % 2 == 0) {
        temp ~/= 2;
      }
    }

    for (int p = 3; p * p <= temp; p += 2) {
      if (temp % p == 0) {
        largestPrime = p;
        while (temp % p == 0) {
          temp ~/= p;
        }
      }
    }

    if (temp > 1) {
      largestPrime = temp;
    }

    modSum += largestPrime % 4;
  }

  return modSum / 4.0;
}

