import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<List<int>> readings, int waterline) {
  final List<List<int>> rects = <List<int>>[];
  final List<int> xs = <int>[], ys = <int>[];
  int? minPlus, maxPlus, minMinus, maxMinus;

  for (final List<int> reading in readings) {
    if (reading.length < 5 || reading[4] < waterline) continue;
    int x1 = reading[0], y1 = reading[1], x2 = reading[2], y2 = reading[3];
    if (x1 == x2 || y1 == y2) continue;
    if (x1 > x2) { final int t = x1; x1 = x2; x2 = t; }
    if (y1 > y2) { final int t = y1; y1 = y2; y2 = t; }
    rects.add(<int>[x1, y1, x2, y2]);
    xs.add(x1); xs.add(x2); ys.add(y1); ys.add(y2);
    final List<List<int>> corners = <List<int>>[
      <int>[x1, y1], <int>[x1, y2], <int>[x2, y1], <int>[x2, y2]
    ];
    for (final List<int> p in corners) {
      final int plus = p[0] + p[1], minus = p[0] - p[1];
      minPlus = minPlus == null || plus < minPlus ? plus : minPlus;
      maxPlus = maxPlus == null || plus > maxPlus ? plus : maxPlus;
      minMinus = minMinus == null || minus < minMinus ? minus : minMinus;
      maxMinus = maxMinus == null || minus > maxMinus ? minus : maxMinus;
    }
  }
  if (rects.isEmpty) return <String, int>{'floodedArea': 0, 'doubleReadArea': 0, 'tideSpan': 0};

  xs.sort(); ys.sort();
  final List<int> ux = <int>[], uy = <int>[];
  for (final int x in xs) { if (ux.isEmpty || ux.last != x) ux.add(x); }
  for (final int y in ys) { if (uy.isEmpty || uy.last != y) uy.add(y); }
  final Map<int, int> xi = <int, int>{}, yi = <int, int>{};
  for (int i = 0; i < ux.length; i++) { xi[ux[i]] = i; }
  for (int i = 0; i < uy.length; i++) { yi[uy[i]] = i; }

  final List<List<int>> count = List<List<int>>.generate(ux.length - 1, (_) => List<int>.filled(uy.length - 1, 0));
  for (final List<int> r in rects) {
    for (int i = xi[r[0]]!; i < xi[r[2]]!; i++) {
      for (int j = yi[r[1]]!; j < yi[r[3]]!; j++) { count[i][j]++; }
    }
  }

  int floodedArea = 0, doubleReadArea = 0;
  for (int i = 0; i < count.length; i++) {
    for (int j = 0; j < count[i].length; j++) {
      if (count[i][j] == 0) continue;
      final int area = (ux[i + 1] - ux[i]) * (uy[j + 1] - uy[j]);
      floodedArea += area;
      if (count[i][j] > 1) doubleReadArea += area;
    }
  }
  final int tideSpan = (maxPlus! - minPlus!) > (maxMinus! - minMinus!) ? (maxPlus - minPlus) : (maxMinus - minMinus);
  return <String, int>{'floodedArea': floodedArea, 'doubleReadArea': doubleReadArea, 'tideSpan': tideSpan};
}

