int fn0(List<List<int>> passGrid) {
  if (passGrid.isEmpty || passGrid[0].isEmpty) {
    return 0;
  }

  int rows = passGrid.length;
  int cols = passGrid[0].length;
  List<List<int>> dp = List.generate(
    rows,
    (_) => List.filled(cols, 0),
  );

  for (int c = 0; c < cols; c++) {
    dp[0][c] = passGrid[0][c];
  }

  int best = 0;

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      dp[r][c] = passGrid[r][c];

      if (r > 0) {
        dp[r][c] = dp[r - 1][c] + passGrid[r][c] > dp[r][c]
            ? dp[r - 1][c] + passGrid[r][c]
            : dp[r][c];
      }

      if (r > 1) {
        for (int prev = 0; prev < cols; prev++) {
          if (prev != c) {
            int switched = dp[r - 2][prev] + passGrid[r][c];
            if (switched > dp[r][c]) {
              dp[r][c] = switched;
            }
          }
        }
      }

      if (dp[r][c] > best) {
        best = dp[r][c];
      }
    }
  }

  return best;
}

