  if (packets.isEmpty) return [0, 0];
  List<int> xs = [];
  List<int> ys = [];
  for (var p in packets) {
    int x = p[0], y = p[1], w = p[2], h = p[3];
    xs.add(x);
    xs.add(x + w);
    ys.add(y);
    ys.add(y + h);
  }
  xs = xs.toSet().toList()..sort();
  ys = ys.toSet().toList()..sort();
  int totalArea = 0;
  int overlapArea = 0;
  for (int i = 0; i < xs.length - 1; i++) {
    int dx = xs[i+1] - xs[i];
    for (int j = 0; j < ys.length - 1; j++) {
      int dy = ys[j+1] - ys[j];
      int count = 0;
      for (var p in packets) {
        int x = p[0], y = p[1], w = p[2], h = p[3];
        if (xs[i] >= x && xs[i+1] <= x + w && ys[j] >= y && ys[j+1] <= y + h) {
          count++;
        }
      }
      if (count > 0) totalArea += dx * dy;
      if (count >= 2) overlapArea += dx * dy;
    }
  }
  return [totalArea, overlapArea];
}

