    }

    int endName = script.indexOf(']', i);
    if (endName == -1) {
      break;
    }

    String name = script.substring(i + 1, endName).trim();
    i = endName + 1;

    while (i < script.length && script[i] == ' ') {
      i++;
    }
    if (i >= script.length || script[i] != ':') {
      break;
    }
    i++;

    int total = result[name] ?? 0;
    StringBuffer token = StringBuffer();
    bool inQuotes = false;
    bool escaping = false;

    while (i <= script.length) {
      String ch = i < script.length ? script[i] : ';';

      if (escaping) {
        token.write(ch);
        escaping = false;
      } else if (inQuotes && ch == '\\') {
