        if (part.isNotEmpty) {
          int count = 1;
          int star = part.lastIndexOf('*');
          if (star > 0) {
            String repeat = part.substring(star + 1).trim();
            if (repeat.isNotEmpty) {
              int? parsed = int.tryParse(repeat);
              if (parsed != null && parsed > 0) {
                count = parsed;
              }
            }
          }
          total += count;
        }

        token.clear();
        if (ch == ';') {
          i++;
          break;
        }
      } else {
        token.write(ch);
      }

      i++;
    }

    result[name] = total;
  }

  return result;
}

