double fn0(int rows, int seatsPerRow, List<List<int>> occupied) {
  if (rows <= 0 || seatsPerRow <= 0) return -1.0;
  final int base = seatsPerRow + 1;
  final Set<int> occupiedCodes = <int>{};
  for (final pair in occupied) {
    if (pair.length == 2) {
      final int r = pair[0];
      final int s = pair[1];
      if (r >= 1 && r <= rows && s >= 1 && s <= seatsPerRow) {
        occupiedCodes.add(r * base + s);
      }
    }
  }
  bool isPrime(int n) {
    if (n < 2) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    for (int i = 3; i * i <= n; i += 2) {
      if (n % i == 0) return false;
    }
    return true;
  }
  final List<int> codes = <int>[];
  for (int r = 1; r <= rows; r++) {
    if (!isPrime(r)) continue;
    for (int s = 1; s <= seatsPerRow; s++) {
      final int code = r * base + s;
      if (!occupiedCodes.contains(code)) {
        codes.add(code);
      }
    }
  }
  if (codes.isEmpty) return -1.0;
  codes.sort();
  final int n = codes.length;
  if (n % 2 == 1) {
    return codes[n ~/ 2].toDouble();
  } else {
    return (codes[n ~/ 2 - 1] + codes[n ~/ 2]) / 2.0;
  }
}

