Map<String, int> fn0(String code) {
  final result = {
    'alpha': 0, 'numeric': 0, 'symbol': 0, 'compound': 0,
    'transitions': 0, 'alpha_then_numeric': 0
  };
  final tokens = code.split(' ').where((t) => t.isNotEmpty).toList();
  if (tokens.isEmpty) return result;
  String classify(String token) {
    bool hasA = false, hasD = false, hasO = false;
    for (int i = 0; i < token.length; i++) {
      final c = token.codeUnitAt(i);
      if ((c >= 65 && c <= 90) || (c >= 97 && c <= 122)) hasA = true;
      else if (c >= 48 && c <= 57) hasD = true;
      else hasO = true;
    }
    final kinds = (hasA ? 1 : 0) + (hasD ? 1 : 0) + (hasO ? 1 : 0);
    if (kinds > 1) return 'compound';
    if (hasA) return 'alpha';
    if (hasD) return 'numeric';
    return 'symbol';
  }
  String prev = '';
  for (final token in tokens) {
    final type = classify(token);
    result[type] = result[type]! + 1;
    if (prev.isNotEmpty && prev != type) {
      result['transitions'] = result['transitions']! + 1;
    }
    if (prev == 'alpha' && type == 'numeric') {
      result['alpha_then_numeric'] = result['alpha_then_numeric']! + 1;
    }
    prev = type;
  }
  return result;
}

