double fn0(String s1, String s2) {
  bool isVowel(String c) => 'aeiou'.contains(c);
  int m = s1.length, n = s2.length;
  List<List<double>> dp = List.generate(m + 1, (_) => List.filled(n + 1, 0.0));
  for (int i = 0; i <= m; i++) dp[i][0] = i.toDouble();
  for (int j = 0; j <= n; j++) dp[0][j] = j.toDouble();
  for (int i = 1; i <= m; i++) {
    for (int j = 1; j <= n; j++) {
      bool v1 = isVowel(s1[i - 1]);
      bool v2 = isVowel(s2[j - 1]);
      double cost = (s1[i - 1] == s2[j - 1]) ? 0.0 : (v1 == v2 ? (v1 ? 0.5 : 1.0) : 1.5);
      dp[i][j] = [dp[i - 1][j] + 1.0, dp[i][j - 1] + 1.0, dp[i - 1][j - 1] + cost]
          .reduce((a, b) => a < b ? a : b);
    }
  }
  return dp[m][n];
}

