@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<List<int>> placements) {
  final Map<int, List<List<int>>> bySquare = {};
  for (final p in placements) {
    if (p.length < 3) continue;
    final int sq = p[0];
    final int s = p[1];
    final int e = p[2];
    if (sq < 0 || sq > 63) continue;
    if (e <= s) continue;
    bySquare.putIfAbsent(sq, () => <List<int>>[]).add(<int>[s, e]);
  }
  final Map<String, int> result = {};
  bySquare.forEach((int sq, List<List<int>> intervals) {
    intervals.sort((List<int> a, List<int> b) => a[0].compareTo(b[0]));
    int total = 0;
    int cs = intervals[0][0];
    int ce = intervals[0][1];
    for (int i = 1; i < intervals.length; i++) {
      final int ns = intervals[i][0];
      final int ne = intervals[i][1];
      if (ns <= ce) {
        if (ne > ce) ce = ne;
      } else {
        total += ce - cs;
        cs = ns;
        ce = ne;
      }
    }
    total += ce - cs;
    if (total > 0) {
      final int file = sq % 8;
      final int rank = sq ~/ 8;
      final String name =
          String.fromCharCode('a'.codeUnitAt(0) + file) + (rank + 1).toString();
      result[name] = total;
    }
  });
  return result;
}

