String fn0(List<List<int>> rects) {
  if (rects.isEmpty) return "0";
  Set<int> xs = {};
  Set<int> ys = {};
  List<List<int>> normalized = [];
  for (var r in rects) {
    int x1 = r[0] < r[2] ? r[0] : r[2];
    int x2 = r[0] < r[2] ? r[2] : r[0];
    int y1 = r[1] < r[3] ? r[1] : r[3];
    int y2 = r[1] < r[3] ? r[3] : r[1];
    if (x1 < x2 && y1 < y2) {
      normalized.add([x1, y1, x2, y2]);
      xs.add(x1);
      xs.add(x2);
      ys.add(y1);
      ys.add(y2);
    }
  }
  if (normalized.isEmpty) return "0";

  List<int> sortedXs = xs.toList()..sort();
  List<int> sortedYs = ys.toList()..sort();

  int totalArea = 0;
  for (int i = 0; i < sortedXs.length - 1; i++) {
    for (int j = 0; j < sortedYs.length - 1; j++) {
      int cx1 = sortedXs[i];
      int cx2 = sortedXs[i + 1];
      int cy1 = sortedYs[j];
      int cy2 = sortedYs[j + 1];
      for (var r in normalized) {
        if (cx1 >= r[0] && cx2 <= r[2] && cy1 >= r[1] && cy2 <= r[3]) {
          totalArea += (cx2 - cx1) * (cy2 - cy1);
