    heights[c] = h;
  }
  final peaks = <int>[];
  var current = 0;
  var inTower = false;
  for (final h in heights) {
    if (h > 0) {
      inTower = true;
      if (h > current) current = h;
    } else if (inTower) {
      peaks.add(current);
      current = 0;
      inTower = false;
    }
  }
  if (inTower) peaks.add(current);
  return peaks;
}

