bool fn0(int sample) {
  const int reservedMask = 0xFFE00000;
  const int parityBitMask = 0x00100000;
  const int lower20Mask = 0x000FFFFF;
  const int errorCodeMask = 0x000F0000;
  const int calFlagMask = 0x00001000;

  if ((sample & reservedMask) != 0) {
    return false;
  }

  int parityBit = (sample >> 20) & 1;
  int lower20 = sample & lower20Mask;
  int computedParity = 0;
  int temp = lower20;
  while (temp != 0) {
    computedParity ^= (temp & 1);
    temp >>= 1;
  }
  if (parityBit != computedParity) {
    return false;
  }

  int errorCode = (sample & errorCodeMask) >> 16;
  if (errorCode > 3) {
    return false;
  }

  if (errorCode != 0 && (sample & calFlagMask) == 0) {
    return false;
  }

  return true;
}

