bool fn0(List<int> redDays, List<int> greenDays, List<int> blueDays) {
  List<List<int>> mergeDays(List<int> days) {
    if (days.isEmpty) return [];
    List<int> sorted = List<int>.from(days);
    sorted.sort();
    List<int> unique = [];
    for (int d in sorted) {
      if (unique.isEmpty || unique.last != d) unique.add(d);
    }
    List<List<int>> intervals = [];
    int start = unique[0];
    int end = unique[0];
    for (int i = 1; i < unique.length; i++) {
      if (unique[i] == end + 1) {
        end = unique[i];
      } else {
        intervals.add([start, end]);
        start = unique[i];
        end = unique[i];
      }
    }
    intervals.add([start, end]);
    return intervals;
  }
  bool intervalsOverlap(List<int> a, List<int> b) {
    return !(a[1] < b[0] || b[1] < a[0]);
  }
  List<List<int>> redIntervals = mergeDays(redDays);
  List<List<int>> greenIntervals = mergeDays(greenDays);
  List<List<int>> blueIntervals = mergeDays(blueDays);
  for (List<int> ri in redIntervals) {
    for (List<int> gi in greenIntervals) {
      if (intervalsOverlap(ri, gi)) return false;
    }
    for (List<int> bi in blueIntervals) {
      if (intervalsOverlap(ri, bi)) return false;
    }
  }
  for (List<int> gi in greenIntervals) {
    for (List<int> bi in blueIntervals) {
      if (intervalsOverlap(gi, bi)) return false;
    }
  }
  return true;
}

