/// Returns a list where each element is the number of isolated available
/// seats (represented by 0) in the corresponding row of the seating chart.
/// A seat is considered isolated if it is available and has no adjacent
/// available seats (left and right are either occupied/blocked or edges).
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<List<int>> seatingChart) {
  List<int> isolatedCounts = [];
  for (List<int> row in seatingChart) {
    int count = 0;
    int n = row.length;
    for (int i = 0; i < n; i++) {
      if (row[i] == 0) {
        bool leftClear = (i == 0) || (row[i - 1] != 0);
        bool rightClear = (i == n - 1) || (row[i + 1] != 0);
        if (leftClear && rightClear) {
          count++;
        }
      }
    }
    isolatedCounts.add(count);
  }
  return isolatedCounts;
}

