double fn0(List<int> energies) {
  final int n = energies.length;
  if (n == 0) return 0.0;
  if (n % 2 != 0) return -1.0;

  final List<double> dp = List<double>.filled(n + 1, -1.0);
  dp[0] = 0.0;

  for (int i = 2; i <= n; i++) {

    if (i == 2 || energies[i - 2] > energies[i - 3]) {
      if (dp[i - 2] >= 0.0) {
        final double avg = (energies[i - 2] + energies[i - 1]) / 2.0;
        final double cand = dp[i - 2] + avg;
        if (cand > dp[i]) dp[i] = cand;
      }
    }

    if (i >= 4) {
      if (i == 4 || energies[i - 4] > energies[i - 5]) {
        if (dp[i - 4] >= 0.0) {
          final double avg = (energies[i - 4] + energies[i - 3] + energies[i - 2] + energies[i - 1]) / 4.0;
          final double cand = dp[i - 4] + avg;
          if (cand > dp[i]) dp[i] = cand;
        }
      }
    }
  }

  return dp[n] >= 0.0 ? dp[n] : -1.0;
}

