double fn0(List<String> rows) {
  if (rows.isEmpty) return 0.0;
  int rootRow = -1, rootCol = -1;
  for (int i = 0; i < rows.length; i++) {
    for (int j = 0; j < rows[i].length; j++) {
      int c = rows[i].codeUnitAt(j);
      if (c >= 65 && c <= 90) {
        rootRow = i;
        rootCol = j;
        break;
      }
    }
    if (rootRow != -1) break;
  }
  if (rootRow == -1) return 0.0;

  double parse(int r, int c) {
    if (r < 0 || r >= rows.length || c < 0) return 0.0;
    if (c >= rows[r].length) return 0.0;
    int charCode = rows[r].codeUnitAt(c);
    if (charCode < 65 || charCode > 90) return 0.0;
    double val = (charCode - 64).toDouble();
    double leftW = 0.0, rightW = 0.0;
    int nextR = r + 1;
    if (nextR < rows.length) {
      String branchRow = rows[nextR];
      int leftCol = c - 1;
      int rightCol = c + 1;
      if (leftCol >= 0 && leftCol < branchRow.length && branchRow.codeUnitAt(leftCol) == 47) {
        leftW = parse(r + 2, c - 2);
      }
      if (rightCol < branchRow.length && branchRow.codeUnitAt(rightCol) == 92) {
        rightW = parse(r + 2, c + 2);
      }
    }
    return val + 0.5 * leftW + 0.5 * rightW;
  }

  return parse(rootRow, rootCol);
}

