Set<int> fn0(List<int> xs, List<int> ys, List<int> widths, List<int> heights, int markerX, int markerY, int maxDistance) {
  Set<int> result = <int>{};

  for (int i = 0; i < xs.length; i++) {
    bool containsMarker = markerX >= xs[i] &&
        markerX < xs[i] + widths[i] &&
        markerY >= ys[i] &&
        markerY < ys[i] + heights[i];

    bool strongOverlap = false;

    for (int j = 0; j < xs.length; j++) {
      if (i == j) {
        continue;
      }

      int overlapWidth = (xs[i] + widths[i] < xs[j] + widths[j]
              ? xs[i] + widths[i]
              : xs[j] + widths[j]) -
          (xs[i] > xs[j] ? xs[i] : xs[j]);

      int overlapHeight = (ys[i] + heights[i] < ys[j] + heights[j]
              ? ys[i] + heights[i]
              : ys[j] + heights[j]) -
          (ys[i] > ys[j] ? ys[i] : ys[j]);

      if (overlapWidth > 0 && overlapHeight > 0) {
        int overlapArea = overlapWidth * overlapHeight;
        if (overlapArea >= 2) {
          strongOverlap = true;
          break;
        }
      }
    }

    int doubledCenterX = xs[i] * 2 + widths[i];
    int doubledCenterY = ys[i] * 2 + heights[i];
    int doubledMarkerX = markerX * 2;
    int doubledMarkerY = markerY * 2;

    int distance = (doubledCenterX - doubledMarkerX).abs() +
        (doubledCenterY - doubledMarkerY).abs();

    if (containsMarker || (strongOverlap && distance <= maxDistance * 2)) {
      result.add(i);
    }
  }

  return result;
}

