double fn0(List<String> barcodes) {
  if (barcodes.isEmpty) return 0.0;
  Map<int, List<String>> dominantGroups = {};
  for (String barcode in barcodes) {
    Map<String, int> freq = {};
    for (int i = 0; i < barcode.length; i++) {
      String d = barcode[i];
      freq[d] = (freq[d] ?? 0) + 1;
    }
    int maxFreq = 0;
    String dominantDigit = '9';
    for (String digit in freq.keys) {
      int count = freq[digit]!;
      if (count > maxFreq || (count == maxFreq && digit.compareTo(dominantDigit) < 0)) {
        maxFreq = count;
        dominantDigit = digit;
      }
    }
    int d = int.parse(dominantDigit);
    if (!dominantGroups.containsKey(d)) {
      dominantGroups[d] = [];
    }
    dominantGroups[d]!.add(barcode);
  }
  int maxCount = 0;
  int superDominant = 9;
  for (int digit in dominantGroups.keys) {
    int count = dominantGroups[digit]!.length;
    if (count > maxCount || (count == maxCount && digit < superDominant)) {
      maxCount = count;
      superDominant = digit;
    }
  }
  List<String> group = dominantGroups[superDominant]!;
  int totalChars = 0;
  int digitCount = 0;
  String target = superDominant.toString();
  for (String barcode in group) {
    totalChars += barcode.length;
    for (int i = 0; i < barcode.length; i++) {
      if (barcode[i] == target) digitCount++;
    }
  }
  if (totalChars == 0) return 0.0;
  return digitCount / totalChars;
}

