  double total = 0.0;
  double prev = entries[0][0];
  for (int i = 0; i < rows; i++) {
    if (i % 2 == 0) {
      for (int j = 0; j < cols; j++) {
        if (i == 0 && j == 0) continue;
        total += (entries[i][j] - prev).abs();
        prev = entries[i][j];
