  int n = bucketCounts.length;
  List<int> fwd = List.filled(n, 0);
  List<int> bwd = List.filled(n, 0);
  List<int> res = List.filled(n, 0);

  fwd[0] = bucketCounts[0];
  for (int i = 1; i < n; i++) {
    fwd[i] = bucketCounts[i] < fwd[i - 1] + 1 ? bucketCounts[i] : fwd[i - 1] + 1;
  }

  bwd[n - 1] = bucketCounts[n - 1];
  for (int i = n - 2; i >= 0; i--) {
    bwd[i] = bucketCounts[i] < bwd[i + 1] + 1 ? bucketCounts[i] : bwd[i + 1] + 1;
  }

  for (int i = 0; i < n; i++) {
    res[i] = fwd[i] < bwd[i] ? fwd[i] : bwd[i];
  }
  return res;
}

