Map<String, int> fn0(String log) {
  int high = 0;
  int low = 0;
  int normal = 0;
  int segments = 0;
  int checksum = 0;
  int longest = 0;

  for (int i = 0; i < log.length; i++) {
    String marker = log[i];

    if (marker == 'H' || marker == 'L' || marker == 'N') {
      int j = i + 1;
      String digits = '';

      while (j < log.length) {
        int code = log.codeUnitAt(j);
        if (code >= 48 && code <= 57) {
          digits += log[j];
          j++;
        } else {
          break;
        }
      }

      if (digits.isNotEmpty) {
        int count = int.parse(digits);

        if (count > 0) {
          segments++;

          if (count > longest) {
            longest = count;
          }

          int value = marker == 'H' ? 5 : (marker == 'L' ? 3 : 1);
          checksum += value * count + segments;

          if (marker == 'H') {
            high += count;
          } else if (marker == 'L') {
            low += count;
          } else {
            normal += count;
          }
        }
      }

      i = j - 1;
    }
  }

  return {
    'high': high,
    'low': low,
    'normal': normal,
    'segments': segments,
    'checksum': checksum,
    'longest': longest,
  };
}

