int fn0(List<List<int>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return 0;
  int rows = grid.length;
  int cols = grid[0].length;
  List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));
  int clusters = 0;
  List<List<int>> dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (grid[r][c].abs() <= 5 && !visited[r][c]) {
        int size = 0;
        List<List<int>> stack = [
          [r, c]
        ];
        visited[r][c] = true;
        while (stack.isNotEmpty) {
          List<int> cell = stack.removeLast();
          int cr = cell[0];
          int cc = cell[1];
          size++;
          for (List<int> d in dirs) {
            int nr = cr + d[0];
            int nc = cc + d[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                !visited[nr][nc] && grid[nr][nc].abs() <= 5) {
              visited[nr][nc] = true;
              stack.add([nr, nc]);
            }
          }
        }
        if (size >= 1) clusters++;
      }
    }
  }
  return clusters;
}

