Map<String, int> fn0(List<List<int>> tideHeights) {
  int poolCount = 0, maxDepth = 0, totalDepth = 0, shallowPools = 0;
  final rows = tideHeights.length;
  if (rows == 0 || tideHeights[0].isEmpty) {
    return {'poolCount': 0, 'maxDepth': 0, 'totalDepth': 0, 'shallowPools': 0};
  }
  final cols = tideHeights[0].length;
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      final h = tideHeights[r][c];
      bool found = false;
      int minN = 0;
      void check(int nr, int nc) {
        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) return;
        final v = tideHeights[nr][nc];
        if (!found || v < minN) minN = v;
        found = true;
      }
      check(r - 1, c); check(r + 1, c); check(r, c - 1); check(r, c + 1);
      if (found && h < minN) {
        final d = minN - h;
        poolCount++; totalDepth += d;
        if (d > maxDepth) maxDepth = d;
        if (d <= 1) shallowPools++;
      }
    }
  }
  return {'poolCount': poolCount, 'maxDepth': maxDepth, 'totalDepth': totalDepth, 'shallowPools': shallowPools};
}

