double fn0(List<int> rowWidths) {
  int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }

  if (rowWidths.length < 2) return 0.0;

  int g = rowWidths[0].abs();
  for (int i = 1; i < rowWidths.length; i++) {
    g = gcd(g, rowWidths[i].abs());
  }
  if (g == 0) return 0.0;

  int n = rowWidths.length;
  int pairCount = n ~/ 2;
  double total = 0.0;

  for (int i = 0; i < pairCount; i++) {
    int j = n - 1 - i;
    int a = rowWidths[i].abs() ~/ g;
    int b = rowWidths[j].abs() ~/ g;
    if (a == b) {
      total += 1.0;
    } else if (gcd(a, b) > 1) {
      total += 0.5;
    }
  }

  return total / pairCount;
}

