  int modBase = modulus == 0 ? 1 : modulus.abs();
  int score = 0;
  for (int i = 0; i < shelfCode.length; i++) {
    int v = shelfCode.codeUnitAt(i);
    v = (v >= 48 && v <= 57) ? v - 48 : (v & 31) + 9;
    bool prime = v > 1;
    for (int d = 2; d * d <= v; d++) {
      if (v % d == 0) {
        prime = false;
        break;
