    if (prime) {
      score += (v * (i + 1)) % modBase;
    } else if (v % 2 == 0) {
      score -= v ~/ 2;
    } else {
      score += v % modBase;
    }
  }
  int a = score.abs(), b = modulus.abs();
  while (b != 0) {
    int t = a % b;
    a = b;
    b = t;
  }
  return a;
}

