bool fn0(List<int> minutes) {
  bool solve(List<int> part) {
    if (part.length < 2) {
      return true;
    }
    for (int pivot = 0; pivot < part.length; pivot++) {
      int hub = part[pivot];
      List<int> earlier = [];
      List<int> later = [];
      bool ok = true;
      for (int i = 0; i < part.length; i++) {
        if (i == pivot) continue;
        int gap = (part[i] - hub).abs();
        if (gap == 0 || gap > 30) {
