      if (d1 > d2) {
        shouldSwap = true;
      } else if (d1 == d2 && lst[j].length > lst[j + 1].length) {
        shouldSwap = true;
      } else if (d1 == d2 && lst[j].length == lst[j + 1].length && lst[j].compareTo(lst[j + 1]) > 0) {
        shouldSwap = true;
      }
      if (shouldSwap) {
        String tmp = lst[j];
        lst[j] = lst[j + 1];
        lst[j + 1] = tmp;
        swaps++;
      }
    }
  }
  return swaps;
}

