    i++; 
    int numStart2 = i;
    while (i < bracketResult.length && bracketResult[i].codeUnitAt(0) >= 48 && bracketResult[i].codeUnitAt(0) <= 57) i++;
    if (i == numStart2) { i++; continue; }
