    int cycleStart = (i ~/ 3) + 1;
    if (count == 1) {
      result.add("Cycle $cycleStart: G=$g,Y=$y,R=$r");
    } else {
      result.add("Cycles ${cycleStart}-${cycleStart + count - 1}: G=$g,Y=$y,R=$r (x$count)");
    }
    i = j;
  }
  return result;
}

