@pragma('vm:never-inline')
@pragma('vm:entry-point')

double fn0(List<int> departures, List<int> arrivals, int maxDelay) {
  final n = departures.length;
  if (n == 0) return 0.0;
  final points = <List<int>>[];
  for (var i = 0; i < n; i++) {
    final d = departures[i], a = arrivals[i];
    points.add([d, a]);
    if (maxDelay != 0) points.add([d, a + maxDelay]);
  }
  points.sort((a, b) => a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
  final unique = <List<int>>[];
  for (final p in points) {
    if (unique.isEmpty || unique.last[0] != p[0] || unique.last[1] != p[1]) unique.add(p);
  }
  if (unique.length < 3) return 0.0;
  int cross(List<int> o, List<int> a, List<int> b) =>
      (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  final lower = <List<int>>[];
  for (final p in unique) {
    while (lower.length >= 2 && cross(lower[lower.length - 2], lower.last, p) <= 0) lower.removeLast();
    lower.add(p);
  }
  final upper = <List<int>>[];
  for (var i = unique.length - 1; i >= 0; i--) {
    final p = unique[i];
    while (upper.length >= 2 && cross(upper[upper.length - 2], upper.last, p) <= 0) upper.removeLast();
    upper.add(p);
  }
  lower.removeLast();
  upper.removeLast();
  final hull = <List<int>>[]..addAll(lower)..addAll(upper);
  if (hull.length < 3) return 0.0;
  var area2 = 0;
  for (var i = 0; i < hull.length; i++) {
    final j = (i + 1) % hull.length;
    area2 += hull[i][0] * hull[j][1] - hull[j][0] * hull[i][1];
  }
  return area2.abs() / 2.0;
}

