int fn0(String tally) {
  if (tally.isEmpty) return -1;

  Map<String, int> votes = {};
  List<String> entries = tally.split(',');

  for (String entry in entries) {
    List<String> parts = entry.split(':');
    if (parts.length != 2) continue;
    String name = parts[0].trim();
    if (name.isEmpty) continue;
    int? count = int.tryParse(parts[1].trim());
    if (count == null || count < 0) continue;
    votes[name] = (votes[name] ?? 0) + count;
  }

  if (votes.isEmpty) return -1;

  int maxVotes = -1;
  bool tie = false;
  for (int v in votes.values) {
    if (v > maxVotes) {
      maxVotes = v;
      tie = false;
    } else if (v == maxVotes) {
      tie = true;
    }
  }

  return tie ? -1 : maxVotes;
}

