      if (stack.isEmpty) return false;
      int roll = int.parse(event[1]);
      int next = stack.removeLast() + roll;
      if (roll < 1 || roll > 6 || next > 9) return false;
      stack.add(next);
    } else {
      return false;
    }
  }
  return stack.isEmpty;
}

