    if (pdB != pdA) return pdB - pdA;
    return (a[0] as String).compareTo(b[0] as String);
  });
  StringBuffer sb = StringBuffer('$groupName: ');
  for (int i = 0; i < parsed.length; i++) {
    if (i > 0) sb.write(' ');
    sb.write('${i + 1}.${parsed[i][0]}');
  }
  return sb.toString();
}

