  int score = 0;
  for (int i = 0; i < bins.length; i++) {
    score += bins[i] == 2 ? 3 : (bins[i] == 1 ? 1 : -2);
    if (i > 0 && bins[i] != bins[i - 1]) score++;
  }
  return score;
}

