    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    common = a;
    if (v > 1) {
      bool prime = true;
      for (int d = 2; d * d <= v; d++) {
        if (v % d == 0) {
          prime = false;
          break;
        }
      }
      rarity += prime ? v : -v;
    }
  }
  if (crates.isEmpty) return 'empty';
  int seal = common.abs() + rarity.abs();
  return '${common}:${seal.toRadixString(16)}';
}

