Map<String, int> fn0(String dna) {
  final Map<String, int> result = {
    'gcRich': 0,
    'balanced': 0,
    'atRich': 0,
  };

  const String bases = 'ACGT';

  void search(int index, String previous, int gcCount, int atCount) {
    if (index == dna.length) {
      if (gcCount > atCount) {
        result['gcRich'] = result['gcRich']! + 1;
      } else if (gcCount == atCount) {
        result['balanced'] = result['balanced']! + 1;
      } else {
        result['atRich'] = result['atRich']! + 1;
      }
      return;
    }

    String current = dna[index];
    String options = current == 'N' ? bases : current;

    for (int i = 0; i < options.length; i++) {
      String base = options[i];
      if (base == previous) {
        continue;
      }

      int nextGc = gcCount + ((base == 'C' || base == 'G') ? 1 : 0);
      int nextAt = atCount + ((base == 'A' || base == 'T') ? 1 : 0);
      search(index + 1, base, nextGc, nextAt);
    }
  }

  search(0, '', 0, 0);
  return result;
}

