@pragma('vm:never-inline')
@pragma('vm:entry-point')

double fn0(int teamCount, int startDay, List<int> roundIntervals, int minimumRestDays) {
  if (teamCount <= 1) {
    return 0.0;
  }

  int bracketSize = 1;
  while (bracketSize < teamCount) {
    bracketSize *= 2;
  }

  int rounds = 0;
  int temp = bracketSize;
  while (temp > 1) {
    temp ~/= 2;
    rounds++;
  }

  List<int> roundDays = List<int>.filled(rounds, startDay);
  for (int i = 1; i < rounds; i++) {
    int gapIndex = i - 1;
    int gap = gapIndex < roundIntervals.length
        ? roundIntervals[gapIndex]
        : roundIntervals.isEmpty
            ? 0
            : roundIntervals.last;
    roundDays[i] = roundDays[i - 1] + gap;
  }

  int byeCount = bracketSize - teamCount;

  int noByePenalty = 0;
  for (int i = 1; i < rounds; i++) {
    int gap = roundDays[i] - roundDays[i - 1];
    if (gap < minimumRestDays) {
      noByePenalty += minimumRestDays - gap;
    }
  }

  int byePenalty = 0;
  if (byeCount > 0 && rounds > 1) {
    for (int i = 2; i < rounds; i++) {
      int gap = roundDays[i] - roundDays[i - 1];
      if (gap < minimumRestDays) {
        byePenalty += minimumRestDays - gap;
      }
    }
  } else {
    byePenalty = noByePenalty;
  }

  return (noByePenalty - byePenalty) / 2.0;
}

