String fn0(int departures, int currentMinute) {
  const int minuteMask = (1 << 60) - 1;
  int schedule = departures & minuteMask;
  if (currentMinute < 0 || currentMinute > 59) return 'Invalid';
  if (schedule == 0) return 'No service';
  int past = (1 << (currentMinute + 1)) - 1;
  int future = schedule & ~past;
  bool wrapped = false;
  if (future == 0) { wrapped = true; future = schedule; }
  int lsb = future & -future;
  int next = lsb.bitLength - 1;
  int end = next + 14;
  int window = end >= 59 ? minuteMask : (1 << (end + 1)) - 1;
  int before = (1 << next) - 1;
  int cluster = schedule & window & ~before;
  int count = 0;
  int temp = cluster;
  while (temp != 0) { count++; temp &= temp - 1; }
  String density;
  if (count >= 5) { density = 'high'; }
  else if (count >= 3) { density = 'medium'; }
  else { density = 'low'; }
  return wrapped ? 'Next at $next (next hour), Density: $density' : 'Next at $next, Density: $density';
}

