String fn0(List<int> gaps) {
  int day = 0;
  int streak = 0;
  int bestStreak = 0;
  int monthWraps = 0;
  for (final gap in gaps) {
    if (gap <= 0) {
      streak = 0;
    } else {
      int previous = day;
      day += gap;
      if (gap == 1) {
        streak++;
      } else if (gap <= 3) {
        streak = 1;
      } else {
        streak = 0;
      }
      if (streak > bestStreak) bestStreak = streak;
      if (previous ~/ 30 != day ~/ 30) monthWraps++;
    }
  }
  int idleDays = 0;
  for (final gap in gaps) {
    if (gap > 3) idleDays += gap - 3;
  }
  return '$day|$bestStreak|$monthWraps|$idleDays';
}

