@pragma('vm:never-inline')
@pragma('vm:entry-point')

int fn0(String script, int startFloor) {
  int currentFloor = startFloor;
  int totalDistance = 0;
  final List<int> requests = [];

  void execute(String segment, int times) {
    for (int t = 0; t < times; t++) {
      int i = 0;
      while (i < segment.length) {
        String ch = segment[i];

        if (ch == ' ' || ch == ',' || ch == '\n' || ch == '\t') {
          i++;
        } else if (ch == 'R' || ch == 'C') {
          bool cancel = ch == 'C';
          i++;
          int sign = 1;
          if (i < segment.length && (segment[i] == '-' || segment[i] == '+')) {
            sign = segment[i] == '-' ? -1 : 1;
            i++;
          }
          int value = 0;
          while (i < segment.length) {
            int digit = segment.codeUnitAt(i) - 48;
            if (digit < 0 || digit > 9) break;
            value = value * 10 + digit;
            i++;
          }
          value *= sign;
          if (value >= -50 && value <= 50) {
            if (cancel) {
              requests.removeWhere((v) => v == value);
            } else {
              requests.add(value);
            }
          }
        } else if (ch == 'S') {
          if (requests.isNotEmpty) {
            int bestIndex = 0;
            int bestDistance = (requests[0] - currentFloor).abs();
            for (int j = 1; j < requests.length; j++) {
              int d = (requests[j] - currentFloor).abs();
              if (d < bestDistance ||
                  (d == bestDistance && requests[j] < requests[bestIndex])) {
                bestIndex = j;
                bestDistance = d;
              }
            }
            currentFloor = requests.removeAt(bestIndex);
            totalDistance += bestDistance;
          }
          i++;
        } else if (ch == '(') {
          int depth = 1;
          int start = ++i;
          while (i < segment.length && depth > 0) {
            if (segment[i] == '(') depth++;
            if (segment[i] == ')') depth--;
            i++;
          }
          String inner = segment.substring(start, i - 1);
          int repeat = 0;
          while (i < segment.length) {
            int digit = segment.codeUnitAt(i) - 48;
            if (digit < 0 || digit > 9) break;
            repeat = repeat * 10 + digit;
            i++;
          }
          execute(inner, repeat == 0 ? 1 : repeat);
        } else {
          i++;
        }
      }
    }
  }

  execute(script, 1);
  return totalDistance;
}

