        if (resistances[mid] == target) { last = mid; low = mid + 1; }
        else if (resistances[mid] < target) low = mid + 1;
        else high = mid - 1;
      }
      results.add('${first + 1}:${last + 1}');
    } else {
      results.add('-1');
    }
  }
  return results;
}

