Map<String, int> fn0(List<List<int>> maze) {
  if (maze.isEmpty) return {};
  int rows = maze.length;
  int cols = maze[0].length;
  List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, 0));
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (maze[r][c] == 1) {
        dp[r][c] = 0;
      } else {
        if (r == 0 && c == 0) {
          dp[r][c] = 1;
        } else {
          int ways = 0;
          if (r > 0) ways += dp[r-1][c];
          if (c > 0) ways += dp[r][c-1];
          dp[r][c] = ways;
        }
      }
    }
  }
  Map<String, int> result = {};
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      result["${r},${c}"] = dp[r][c];
    }
  }
  return result;
}

