bool fn0(String logs) {
  int primeCount = 0, compositeCount = 0, current = -1;
  for (int i = 0; i <= logs.length; i++) {
    int ch = i < logs.length ? logs.codeUnitAt(i) : 35;
    if (i < logs.length && ch >= 48 && ch <= 57) {
      current = current < 0 ? ch - 48 : current * 10 + ch - 48;
