      if (current > 1) {
        bool prime = true;
        for (int d = 2; d * d <= current; d++) {
          if (current % d == 0) { prime = false; break; }
        }
        if (prime) { primeCount++; } else { compositeCount++; }
      }
      current = -1;
    }
  }
  if (primeCount + compositeCount == 0) return false;
  int a = primeCount, b = compositeCount;
  while (b != 0) { int t = a % b; a = b; b = t; }
  return a == 1;
}

