  int x = 0, y = 0;
  List<int> xs = [0];
  List<int> ys = [0];

  for (int i = 0; i < sequence.length; i++) {
    String ch = sequence[i];

    if (ch != 'A' && ch != 'C' && ch != 'G' && ch != 'T') {
      return 0.0; 
