String fn0(List<List<int>> ledger) {
  if (ledger.isEmpty || ledger[0].isEmpty) return '';
  int rows = ledger.length;
  int cols = ledger[0].length;
  List<String> flags = [];
  int top = 0, bottom = rows - 1, left = 0, right = cols - 1;
  int dir = 0;
  while (top <= bottom && left <= right) {
    if (dir == 0) {
      for (int c = left; c <= right; c++) {
        if (ledger[top][c] < 0) flags.add('${top}:${c}=${ledger[top][c]}');
      }
      top++;
    } else if (dir == 1) {
      for (int r = top; r <= bottom; r++) {
        if (ledger[r][right] < 0) flags.add('${r}:${right}=${ledger[r][right]}');
      }
      right--;
    } else if (dir == 2) {
      for (int c = right; c >= left; c--) {
        if (ledger[bottom][c] < 0) flags.add('${bottom}:${c}=${ledger[bottom][c]}');
      }
      bottom--;
    } else if (dir == 3) {
      for (int r = bottom; r >= top; r--) {
        if (ledger[r][left] < 0) flags.add('${r}:${left}=${ledger[r][left]}');
      }
      left++;
    }
    dir = (dir + 1) % 4;
  }
  return flags.join(';');
}

