int fn0(List<List<int>> pixelGrid) {
  if (pixelGrid.isEmpty || pixelGrid[0].isEmpty) return 0;
  int rows = pixelGrid.length;
  int cols = pixelGrid[0].length;
  List<List<int>> dpNo = List.generate(rows, (_) => List<int>.filled(cols, 0));
  List<List<int>> dpBo = List.generate(rows, (_) => List<int>.filled(cols, 0));
  dpNo[0][0] = pixelGrid[0][0];
  dpBo[0][0] = pixelGrid[0][0] * 2;
  for (int c = 1; c < cols; c++) {
    int v = pixelGrid[0][c];
    dpNo[0][c] = dpNo[0][c - 1] + v;
    int a = dpBo[0][c - 1] + v;
    int b = dpNo[0][c - 1] + v * 2;
    dpBo[0][c] = a > b ? a : b;
  }
  for (int r = 1; r < rows; r++) {
    int v = pixelGrid[r][0];
    dpNo[r][0] = dpNo[r - 1][0] + v;
    int a = dpBo[r - 1][0] + v;
    int b = dpNo[r - 1][0] + v * 2;
    dpBo[r][0] = a > b ? a : b;
  }
  for (int r = 1; r < rows; r++) {
    for (int c = 1; c < cols; c++) {
      int v = pixelGrid[r][c];
      int bestNo = dpNo[r - 1][c] > dpNo[r][c - 1] ? dpNo[r - 1][c] : dpNo[r][c - 1];
      dpNo[r][c] = bestNo + v;
      int bestBo = dpBo[r - 1][c] > dpBo[r][c - 1] ? dpBo[r - 1][c] : dpBo[r][c - 1];
      int boostNow = bestNo + v * 2;
      dpBo[r][c] = bestBo + v > boostNow ? bestBo + v : boostNow;
    }
  }
  return dpBo[rows - 1][cols - 1];
}

