List<int> fn0(List<int> phaseDurations, List<int> queryTimes) {

  List<int> result = [];
  if (phaseDurations.isEmpty) {
    return List<int>.filled(queryTimes.length, -1);
  }
  List<int> prefix = [];
  int total = 0;
  for (int d in phaseDurations) {
    total += d;
    prefix.add(total);
  }
  for (int t in queryTimes) {
    int m = t % total;
    int lo = 0;
    int hi = prefix.length - 1;
    while (lo < hi) {
      int mid = (lo + hi) ~/ 2;
      if (prefix[mid] > m) {
        hi = mid;
      } else {
        lo = mid + 1;
      }
    }
    result.add(lo);
  }
  return result;
}

