        int up = grid[r - 1][c];
        if (up == 2 && phase == 0) score += 4;
        else if (up == 0 && phase == 2) score += 2;
        else if (up == phase) score -= 1;
      }
    }
  }
  return score < 0 ? 0 : score;
}

