  int total = 0;
  String previous = '';
  for (int i = 0; i < hash; i += 2) {
    if (i + 1 >= hash) return false;
    String song = tape[i];
    int count = tape.codeUnitAt(i + 1) - 48;
    if (!RegExp(r'[A-Z]').hasMatch(song) || count < 1 || count > 9) {
      return false;
