    if (song == previous) {
      if (count.isOdd) return false;
      total += count ~/ 2;
    } else {
      total += 'AEIOU'.contains(song) ? count * 2 : count;
    }
    previous = song;
  }
  return total % 10 == tape.codeUnitAt(hash + 1) - 48;
}

