  const xs = [1, 0, 1, 2, 0, 1, 2, 0, 1, 2];
  const ys = [3, 0, 0, 0, 1, 1, 1, 2, 2, 2];
  if (password.isEmpty) return 0;
  int score = 0;
  for (int i = 0; i < password.length; i++) {
    int d = password.codeUnitAt(i) - 48;
    if (d < 0 || d > 9) {
      score -= 2;
      continue;
    }
    for (int j = 0; j < i; j++) {
