      if (p < 0 || p > 9) continue;
      int dx = (xs[d] - xs[p]).abs();
      int dy = (ys[d] - ys[p]).abs();
      int dist = dx + dy;
      if (dist == 0) {
        score += 5;
        if (i - j == 1) return score;
      } else if (dist == 1) {
        score += 2;
      } else if (dx == dy) {
        score -= 1;
      }
      for (int k = 0; k < j; k++) {
        int q = password.codeUnitAt(k) - 48;
        if (q < 0 || q > 9) continue;
        if (xs[q] == xs[d] && ys[q] == ys[p] && dx > 0 && dy > 0) {
          score += dx * dy;
          break;
        }
      }
    }
  }
  return score;
}

