bool fn0(
    List<String> ingredients, double scaleFactor, String expectedEncoding) {
  List<String> encodedNames = [];
  int digitSum = 0;
  for (String item in ingredients) {
    int colonIdx = item.indexOf(':');
    if (colonIdx == -1) return false;
    String amountStr = item.substring(0, colonIdx);
    String name = item.substring(colonIdx + 1);
    double amount = double.parse(amountStr);
    double scaled = amount * scaleFactor;
    int shift = scaled.truncate();
    String scaledStr = scaled.toString();
    for (int i = 0; i < scaledStr.length; i++) {
      int code = scaledStr.codeUnitAt(i);
      if (code >= 48 && code <= 57) {
        digitSum += code - 48;
      }
    }
    StringBuffer sb = StringBuffer();
    for (int i = 0; i < name.length; i++) {
      int charCode = name.codeUnitAt(i);
      if (charCode >= 97 && charCode <= 122) {
        int shifted = 97 + ((charCode - 97 + shift) % 26);
        sb.writeCharCode(shifted);
      } else {
        sb.writeCharCode(charCode);
      }
    }
    encodedNames.add(sb.toString());
  }
  String encoded = encodedNames.join('|') + ':' + (digitSum % 10).toString();
  return encoded == expectedEncoding;
}

