Set<int> fn0(
    List<List<int>> belts,
    List<int> blockedDays,
    List<int> activeShifts,
    int shiftCycle,
    int horizon) {
  Set<int> blocked = blockedDays.toSet();
  Set<int> validShifts = activeShifts.toSet();
  Set<int> result = {};
  for (int d = 0; d < horizon; d++) {
    if (blocked.contains(d)) continue;
    if (!validShifts.contains(d % shiftCycle)) continue;
    int activeCount = 0;
    for (List<int> belt in belts) {
      int onDay = belt[0];
      int onDuration = belt[1];
      int cycle = belt[2];
      if (d >= onDay) {
        int elapsed = d - onDay;
        if (elapsed % cycle < onDuration) {
          activeCount++;
        }
      }
    }
    if (activeCount > 0 && activeCount % 2 == 1) {
      result.add(d);
    }
  }
  return result;
}

