    if (dbm >= -70) return 'F';
    if (dbm >= -80) return 'P';
    return 'D';
  }
  String result = '';
  String current = bin(readings[0]);
  int count = 1;
  for (int i = 1; i < readings.length; i++) {
    String b = bin(readings[i]);
    if (b == current) {
      count++;
    } else {
      result += '$current$count';
      current = b;
      count = 1;
    }
  }
  result += '$current$count';
  return result;
}

