    int rowA = squareA ~/ 8;
    int colA = squareA % 8;
    for (int j = i + 1; j < records.length; j++) {
      int dayGap = (records[j] ~/ 64) - dayA;
      if (dayGap <= 0) continue;
      int squareB = records[j] % 64;
      int rowB = squareB ~/ 8;
      int colB = squareB % 8;
