        score[1] += dayGap.isOdd ? 1 : 2;
      } else if ((dr == 1 && dc == 2) || (dr == 2 && dc == 1)) {
        score[2] += dayGap % 5;
      } else if (dayGap % 7 == 0) {
        score[2]--;
      }
    }
  }
  return score;
}

