int fn0(String chart, int groupSize) {
  if (groupSize <= 0) return 0;
  const int sStart = 0;
  const int sAvailable = 1;
  const int sOccupied = 2;
  int state = sStart;
  int runLength = 0;
  int blockCount = 0;
  for (int i = 0; i < chart.length; i++) {
    String ch = chart[i];
    if (ch == 'A') {
      if (state == sAvailable) {
        runLength++;
      } else {
        state = sAvailable;
        runLength = 1;
      }
    } else if (ch == 'X') {
      if (state == sAvailable && runLength == groupSize) {
        blockCount++;
      }
      state = sOccupied;
      runLength = 0;
    } else if (ch == '|' || ch == ';') {
      if (state == sAvailable && runLength == groupSize) {
        blockCount++;
      }
      state = sStart;
      runLength = 0;
    }
  }
  if (state == sAvailable && runLength == groupSize) {
    blockCount++;
  }
  return blockCount;
}

