bool fn0(String encoded, int expectedTotal, int maxConsecutive) {
  if (encoded.isEmpty) return expectedTotal == 0;
  final validSensors = {'A', 'B', 'C', 'D', 'E'};
  int total = 0;
  int i = 0;
  while (i < encoded.length) {
    String ch = encoded[i];
    if (ch.codeUnitAt(0) < 65 || ch.codeUnitAt(0) > 90) return false;
    if (!validSensors.contains(ch)) return false;
    i++;
    if (i >= encoded.length) return false;
    int count = 0;
    bool hasDigit = false;
    while (i < encoded.length) {
      int code = encoded[i].codeUnitAt(0);
      if (code >= 48 && code <= 57) {
        count = count * 10 + (code - 48);
        hasDigit = true;
        i++;
      } else {
        break;
      }
    }
    if (!hasDigit || count == 0) return false;
    if (count > maxConsecutive) return false;
    total += count;
  }
  return total == expectedTotal;
}

