String fn0(List<int> packetSizes, int mtu) {
  if (packetSizes.isEmpty) return "No packet fits";
  int low = 0;
  int high = packetSizes.length - 1;
  int result = -1;
  while (low <= high) {
    int mid = low + (high - low) ~/ 2;
    if (packetSizes[mid] <= mtu) {
      result = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  if (result == -1) return "No packet fits";
  return "Largest fitting packet: ${packetSizes[result]} bytes";
}

